def dump(x, n=2400):
    try:
        s = json.dumps(x, ensure_ascii=False, default=str, sort_keys=True)
    except (TypeError, ValueError):
        s = repr(x)
    return s[:n]


def full(x):
    """Необрезающий вывод — контейнер для assertIn/assertNotIn. dump() (обрез n=2400) — только для сообщений:
    обрезанный контейнер даёт ложный красный в assertIn и ложный зелёный в assertNotIn."""
    return json.dumps(x, ensure_ascii=False, default=str, sort_keys=True)


def rcode(out):
    """Код причины исхода: reason = «код [: слова]» (CONTRACT §1.2)."""
    return str((out or {}).get("reason") or "").split(":")[0].strip()


def data(out):
    d = (out or {}).get("data")
    return d if isinstance(d, dict) else {}


def verdict(out):
    """Вердикт ответа: data.verdict (CONTRACT §5.4); у сироты контракт пишет ok(verdict="orphan", data.orphan_id) —
    принимается и верхний ключ."""
    v = data(out).get("verdict")
    return v if v is not None else (out or {}).get("verdict")


def wa(n):
    return {"channel": "wa", "value": n}


def dm(day):
    """'2026-10-12' → '12.10' (подпись даты в вопросе documents_for)."""
    return "%s.%s" % (day[8:10], day[5:7])


def hm(act_ref, author_id=1001, note="синтетика: отдельное действие человека"):
    """Свидетельство human_mark (CONTRACT §3.6)."""
    return {"kind": "human_mark", "ref": act_ref, "author_id": author_id, "act_ref": act_ref, "note": note}


def sha12(*parts):
    return hashlib.sha1("|".join(str(p) for p in parts).encode("utf-8")).hexdigest()[:12]


def cash_idem(cid, f):
    """CONTRACT §11: cash:<case_id>:<row>:<msg_id|link>:<sha(amount|currency|status|booking_id)[:12]>."""
    h = hashlib.sha256(("%s|%s|%s|%s" % (f.get("amount"), f.get("currency"), f.get("status") or "",
                                         f.get("booking_id") or "")).encode("utf-8")).hexdigest()[:12]
    return "cash:%s:%s:%s:%s" % (cid, f.get("row"), f.get("msg_id") or f.get("link"), h)


def walk(x, path="$"):
    if isinstance(x, dict):
        yield path, x
        for k, v in x.items():
            for item in walk(v, "%s.%s" % (path, k)):
                yield item
    elif isinstance(x, (list, tuple)):
        for i, v in enumerate(x):
            for item in walk(v, "%s[%d]" % (path, i)):
                yield item


def params_a(**over):
    """Синтетические значения UNKNOWN-параметров (CONTRACT §14 вариант А) поверх PARAMS_DEFAULT."""
    p = dict(RC.PARAMS_DEFAULT)
    rrp = p.get("RESULT_RECORD_PLACE")
    rrp = dict(rrp) if isinstance(rrp, dict) else {}
    rrp.setdefault("handover", "crm:в аренде")
    rrp.setdefault("return", "crm:завершена")
    rrp["readiness"] = "sink:fake"
    sa = p.get("STAFF_ADDRESSEES")
    sa = dict(sa) if isinstance(sa, dict) else {}
    sa.update({"topic": frozenset([9001]), "delivery": frozenset([9002]), "agents": frozenset([9003])})
    p.update({"AUTO_ASK": True, "STAFF_ADDRESSEES": sa, "RESULT_RECORD_PLACE": rrp,
              "FEEDS_CONNECTED": frozenset(["intervention", "inbound"]), "APPROVER_IDS": frozenset([1001])})
    p.update(over)
    return p


def params_default():
    return dict(RC.PARAMS_DEFAULT)


def default_approver():
    """Одобряющий при PARAMS_DEFAULT: APPROVER_IDS (= OWNER_IDS по CONTRACT §10)."""
    cand = []
    for key in ("APPROVER_IDS", "OWNER_IDS"):
        ids = RC.PARAMS_DEFAULT.get(key)
        if isinstance(ids, (set, frozenset, list, tuple)):
            cand = sorted(i for i in ids if isinstance(i, int) and not isinstance(i, bool))
        if cand:
            break
    return {"kind": "human", "id": cand[0] if cand else 504608015, "name": "owner-default"}


