class H(object):
    def __init__(self, params=None, start=MOMENT, label="w", journal_mode="wal"):
        self.dir = tempfile.mkdtemp(prefix="k4acc_%s_" % label, dir=TTMP)
        self.path = os.path.join(self.dir, "rental_case.db")
        self.clock = F.FakeClock(start)
        self.ids = F.SeqIds()
        self.counters = F.Counters()
        self.params = params if params is not None else params_a()
        self.store_id = RC.Store.create(self.path, clock=self.clock, new_id=self.ids, journal_mode=journal_mode)
        self.stores = {}
        self.extra = []
        self.bridge = F.FakeBridge(self.clock, self.counters)
        self.telegram = F.FakeTelegram(self.clock, self.counters)
        self.staff_ask = F.FakeStaffAsk(self.clock, self.counters)
        self.staff_port = F.FakeStaffAskPort(self.staff_ask, self.telegram, self.clock, TOPIC_CHAT, TOPIC_THREAD,
                                             DELIVERY_CHAT, AGENTS_CHAT, q_ru=Q_RU, q_th=Q_TH)
        self.esc_port = F.FakeEscalationPort(self.staff_ask, self.telegram, self.clock, AGENTS_CHAT)
        self.card_port = F.FakeApprovalPort(self.telegram, self.clock, INBOX_CHAT, self.counters)
        self.notice = F.FakeNoticePort(self.clock, self.counters)
        self.sink = F.FakeResultSink(self.clock, self.counters)
        self.crm = F.FakeCrmReadback(self.clock, self.counters)
        self.cash_port = F.FakeCashPort(self.bridge, self.clock)
        self.contract_port = F.FakeContractPort(self.bridge, self.clock)
        self.pdf_port = F.FakePdfPort(self.bridge, self.clock)
        self.state_port = F.FakeStatePort(self.bridge, self.clock)
        self.delivery = F.FakeDeliveryStatusPort(self.clock, self.counters)

    # --- объекты Store ---
    def store(self, role="test"):
        st = self.stores.get(role)
        if st is None:
            st = RC.Store(self.path, role=role, clock=self.clock, new_id=self.ids, params=self.params)
            self.stores[role] = st
        return st

    def restart(self, role):
        """Рестарт процесса роли: прежний объект закрыт, новый — новый boot_id (CONTRACT §5)."""
        old = self.stores.pop(role, None)
        if old is not None:
            old.close()
        return self.store(role)

    def other_store(self, role, busy_timeout_s=5.0):
        st = RC.Store(self.path, role=role, clock=self.clock, new_id=self.ids, params=self.params,
                      busy_timeout_s=busy_timeout_s)
        self.extra.append(st)
        return st

    def close_all(self):
        for st in list(self.stores.values()) + self.extra:
            try:
                st.close()
            except Exception:                                            # noqa: BLE001 — уборка закрытием, не удалением
                pass
        self.stores = {}
        self.extra = []

    # --- чтение базы (только чтение; схема — CONTRACT §2) ---
    def q(self, sql, args=()):
        con = sqlite3.connect(pathlib.Path(self.path).as_uri() + "?mode=ro", uri=True, timeout=10)
        con.row_factory = sqlite3.Row
        try:
            return [dict(r) for r in con.execute(sql, args).fetchall()]
        finally:
            con.close()

    def one(self, sql, args=()):
        rows = self.q(sql, args)
        return rows[0] if rows else None

    def counts(self):
        return dict((t, self.q("SELECT COUNT(*) AS n FROM %s" % t)[0]["n"]) for t in RC_TABLES)

    def case(self, cid):
        return self.one("SELECT * FROM rc_case WHERE case_id=?", (cid,))

    def ver(self, cid):
        return self.case(cid)["ver"]

    def rental(self, cid):
        return self.one("SELECT * FROM rc_rental WHERE case_id=? AND current=1", (cid,))

    def rentals(self, cid):
        return self.q("SELECT * FROM rc_rental WHERE case_id=? ORDER BY id", (cid,))

    def obligations(self, cid):
        return self.q("SELECT * FROM rc_obligation WHERE case_id=? ORDER BY id", (cid,))

    def obligation(self, cid, kind, role):
        rows = [o for o in self.obligations(cid) if o["kind"] == kind and o["role"] == role]
        return rows[-1] if rows else None

    def documents(self, cid):
        return self.q("SELECT * FROM rc_document WHERE case_id=? ORDER BY id", (cid,))

    def doc(self, did):
        return self.one("SELECT * FROM rc_document WHERE id=?", (did,))

    def doc_id(self, cid, kind, ext_id):
        r = self.one("SELECT id FROM rc_document WHERE case_id=? AND kind=? AND ext_id=? ORDER BY id DESC",
                     (cid, kind, ext_id))
        return r["id"] if r else None

    def expect(self, exp_id):
        return self.one("SELECT * FROM rc_expect WHERE exp_id=?", (exp_id,))

    def expects(self, cid, kind=None):
        rows = self.q("SELECT * FROM rc_expect WHERE case_id=? ORDER BY created_at, exp_id", (cid,))
        return [e for e in rows if kind is None or e["kind"] == kind]

    def task(self, task_id):
        return self.one("SELECT * FROM rc_task WHERE task_id=?", (task_id,))

    def stages(self, task_id):
        return [s["stage"] for s in self.q("SELECT stage FROM rc_stage WHERE task_id=? ORDER BY id", (task_id,))]

    def facts(self, cid, kind=None):
        rows = self.q("SELECT * FROM rc_fact WHERE case_id=? ORDER BY id", (cid,))
        return [f for f in rows if kind is None or f["kind"] == kind]

    def contacts(self, cid):
        return self.q("SELECT * FROM rc_contact WHERE case_id=? ORDER BY id", (cid,))

    def answers(self, exp_id=None):
        if exp_id is None:
            return self.q("SELECT * FROM rc_answer ORDER BY id")
        return self.q("SELECT * FROM rc_answer WHERE exp_id=? ORDER BY id", (exp_id,))

    def posts(self, exp_id):
        return self.q("SELECT * FROM rc_post WHERE exp_id=? ORDER BY at", (exp_id,))

    def notice_row(self, notice_id):
        return self.one("SELECT * FROM rc_notice WHERE notice_id=?", (notice_id,))

    def events(self, cid=None, type_=None):
        if cid is None:
            rows = self.q("SELECT * FROM rc_event ORDER BY seq")
        else:
            rows = self.q("SELECT * FROM rc_event WHERE case_id=? ORDER BY seq", (cid,))
        return [e for e in rows if type_ is None or e["type"] == type_]

    # --- источник (CONTRACT §1.2 Source) ---
    def src(self, name=F.CLIENTS_SOURCE, ref="строка 812", method="door", observed_at=None, read_at=None):
        t = self.clock()
        return {"name": name, "ref": ref, "method": method, "read_at": t if read_at is None else read_at,
                "observed_at": t if observed_at is None else observed_at}

    def open_case(self, st, row, by=CODE, origin="test", observed_at=None, booking_id=None, force_new=False,
                  model_req=None, idem=None, contacts=()):
        s = self.src(ref="строка %s" % row["row"], observed_at=observed_at,
                     read_at=observed_at)
        bk = booking_id if booking_id is not None else (row.get("booking_id") or None)
        key = idem or (("open:%s:bk:%s" % (origin, bk)) if bk else
                       ("open:%s:row:%s:%r" % (origin, s["ref"], s["observed_at"])))
        return st.open_case(origin=origin, by=by, idem_key=key, booking_id=bk, rental_row=row,
                            contacts=list(contacts), source=s, model_req=model_req, force_new=force_new)

    def cash_fact(self, row, amount, day, bike="Nmax 6908", booking_id="", category="rental", description=""):
        self.bridge.cash.append(F.make_cash(row, amount, day, bike=bike, booking_id=booking_id, category=category,
                                            description=description))
        res = self.cash_port.find(bike=bike, date_from=day, date_to=day)
        facts = [f for f in res.get("facts") or [] if f.get("row") == row]
        return (facts[0] if facts else None), res

    def contract(self, row, doc_id, client, contract_date, bike, phone, signed_at, pdf_id=None):
        c = F.make_contract(row, doc_id, client, contract_date, bike, phone, signed_at=signed_at, pdf_id=pdf_id)
        self.bridge.registry = [c]
        if pdf_id:
            self.bridge.pdfs[pdf_id] = {"row": row, "client": client, "contract_date": contract_date,
                                        "signed_at": signed_at}
        return c


