# База проверок: утверждения и сквозные шаги по CONTRACT
# =====================================================================================================================


class K4Case(unittest.TestCase):
    maxDiff = None

    def world(self, **kw):
        h = H(**kw)
        self.addCleanup(h.close_all)
        return h

    # --- утверждения ---
    def assertCode(self, out, code, reason=None, what=""):
        self.assertIsInstance(out, dict, "%s: исход не словарь: %r" % (what, out))
        self.assertEqual(out.get("code"), code, "%s: ждали %s(%s), получили %s" % (what, code, reason or "",
                                                                                 dump(out)))
        if reason is not None:
            self.assertEqual(rcode(out), reason, "%s: причина: %s" % (what, dump(out)))

    def assertReasonIn(self, out, reasons, what=""):
        self.assertIn(rcode(out), reasons, "%s: причина не из %s: %s" % (what, reasons, dump(out)))

    def assertAsk(self, out, what=""):
        """C5/I12 (M12): unknown — с непустыми missing и ask."""
        self.assertIsInstance(out.get("missing"), list, "%s: missing не список: %s" % (what, dump(out)))
        self.assertTrue(out.get("missing"), "%s: missing пуст: %s" % (what, dump(out)))
        self.assertTrue(isinstance(out.get("ask"), str) and out["ask"].strip(), "%s: ask пуст: %s" % (what, dump(out)))

    def assertPicked(self, res, row_no, what=""):
        self.assertEqual(res.get("code"), "found", "%s: %s" % (what, dump(res)))
        self.assertEqual((res.get("row") or {}).get("row"), row_no, "%s: выбрана не та строка: %s" % (what, dump(res)))

    def assertNoWrites(self, h, before, what=""):
        self.assertEqual(h.counts(), before, "%s: исход без записи изменил rc_*" % what)

    def ok_case(self, h, st, row, **kw):
        out = h.open_case(st, row, **kw)
        self.assertCode(out, "ok", what="open_case строки %s" % row["row"])
        cid = out.get("case_id") or data(out).get("case_id")
        self.assertTrue(cid and str(cid).startswith("RC-"), "case_id: %s" % dump(out))
        return cid

    def reconcile(self, h, st, cid, rows, by=CRM, observed_at=None, step=60):
        h.clock.advance(step)
        s = h.src(ref="строки %s" % ",".join(str(r["row"]) for r in rows), observed_at=observed_at)
        return st.reconcile_rental(cid, rows=rows, source=s, by=by,
                                   idem_key="recon:%s:%s:%r" % (cid, s["name"], s["observed_at"]))

    def claim_one(self, h, st, exp_id, kinds, by=SPL):
        got = st.claim_for_posting(by=by, kinds=kinds)
        mine = [e for e in got or [] if e.get("exp_id") == exp_id]
        self.assertEqual(len(mine), 1, "claim_for_posting не отдал %s: %s" % (exp_id, dump(got)))
        self.assertEqual(h.expect(exp_id)["state"], "in_flight")
        exp = dict(mine[0])
        for k, v in h.expect(exp_id).items():
            exp.setdefault(k, v)
        return exp

    def mark(self, h, st, exp_id, result, by=SPL, expect_row_ver=None):
        rv = expect_row_ver if expect_row_ver is not None else h.expect(exp_id)["row_ver"]
        return st.mark_post_result(exp_id, result=result, by=by, idem_key="mark_post_result:%s:%d" % (exp_id, rv),
                                   expect_row_ver=rv)

    def request_q(self, st, cid, ver, task_id=None, staff_kind="байк", q_ru=Q_RU, q_th=Q_TH, by=APPROVER,
                  attempt=1):
        idem = "ask:%s:%s:%s:%s:%d" % (cid, ver, task_id or "-", sha12(staff_kind, q_ru), attempt)
        return st.request_staff_question(cid, task_id=task_id, staff_kind=staff_kind, q_ru=q_ru, q_th=q_th,
                                         urgency="клиент интересуется", by=by, idem_key=idem, expect_ver=ver)

    def ask_and_post(self, h, st_req, st_post, cid, ver, task_id=None, staff_kind="байк", q_ru=Q_RU, q_th=Q_TH,
                     by=APPROVER):
        out = self.request_q(st_req, cid, ver, task_id=task_id, staff_kind=staff_kind, q_ru=q_ru, q_th=q_th, by=by)
        self.assertCode(out, "ok", what="request_staff_question")
        exp_id = data(out)["exp_id"]
        self.assertEqual(h.expect(exp_id)["state"], "planned")
        exp = self.claim_one(h, st_post, exp_id, ("staff_question",))
        res = F.run_coro(h.staff_port.post(exp))
        h.clock.advance(5)
        m = self.mark(h, st_post, exp_id, res)
        return exp_id, res, m

    @staticmethod
    def posted_mid(res, place):
        for p in (res or {}).get("posted") or []:
            if p.get("place") == place:
                return p["msg_id"]
        return None

    def staff_reply(self, h, st, msg_id, reply_to, author_id, text="พร้อมครับ / готов", chat=TOPIC_CHAT,
                    thread_id=TOPIC_THREAD, username=None, is_bot=False, reply_to_is_bot=True, at=None):
        return st.on_staff_answer(chat=chat, msg_id=str(msg_id), reply_to=reply_to, reply_to_is_bot=reply_to_is_bot,
                                  thread_id=thread_id, author_id=author_id,
                                  author_username=username if username is not None else "staff%s" % author_id,
                                  is_bot=is_bot, text=text, at=h.clock() if at is None else at,
                                  by={"kind": "staff", "id": author_id, "name": "staff"})

    def card(self, h, st, cid, ver, action, chat=INBOX_CHAT, ref="card-1", task_id=None, by=SPL):
        idem = "appr:%s%s:%s:%s:%s" % (cid or "-", ver if ver is not None else "-", action, chat, ref)
        out = st.request_approval(cid, task_id=task_id, action=action, chat=chat,
                                  card={"ref": ref, "text": "синтетическая карточка %s" % action}, by=by,
                                  idem_key=idem, expect_ver=ver)
        self.assertCode(out, "ok", what="request_approval(%s)" % action)
        exp_id = data(out)["exp_id"]
        exp = self.claim_one(h, st, exp_id, ("approval",))
        res = F.run_coro(h.card_port.post_card(exp))
        self.assertIn("posted", res, dump(res))
        m = self.mark(h, st, exp_id, res)
        self.assertCode(m, "ok", what="mark_post_result карточки")
        self.assertEqual(h.expect(exp_id)["state"], "waiting")
        return exp_id, res["posted"][0]["msg_id"]

    def yes(self, h, st, msg_id, reply_to, text="да", author_id=1001, chat=INBOX_CHAT, at=None):
        return st.on_approval_reply(chat=chat, msg_id=str(msg_id), reply_to=reply_to,
                                    reply_to_is_bot=reply_to is not None, thread_id=None, author_id=author_id,
                                    author_username="owner", is_bot=False, text=text,
                                    at=h.clock() if at is None else at,
                                    by={"kind": "human", "id": author_id, "name": "owner"})

    def open_task(self, h, st, cid, ver, kind="readiness", ref="wa:in:501", by=APPROVER):
        out = st.open_task(cid, kind=kind, ref=ref, by=by, idem_key="task:%s:%s:%s:%s" % (cid, ver, kind, ref),
                           expect_ver=ver)
        self.assertCode(out, "ok", what="open_task(%s)" % kind)
        tid = data(out).get("task_id")
        if not tid:
            tid = h.one("SELECT task_id FROM rc_task WHERE case_id=? AND kind=? ORDER BY created_at DESC",
                        (cid, kind))["task_id"]
        return tid

    def readback_landed(self, h, st, cid, task_id, ver, check_ok=True):
        """expect_readback(result) → claim_execution → ResultSink.write → mark_written → ResultSink.read →
        on_readback(landed) (CONTRACT §4.2, §14 Д12)."""
        target = {"sink": "fake", "task_id": task_id}
        out = st.expect_readback(cid, task_id=task_id, action="result", target=target, by=SPL,
                                 idem_key="rb:%s:%s:result" % (task_id, ver), expect_ver=ver)
        self.assertCode(out, "ok", what="expect_readback")
        rb = data(out).get("exp_id") or h.q("SELECT exp_id FROM rc_expect WHERE task_id=? AND kind='readback' "
                                            "ORDER BY created_at DESC", (task_id,))[0]["exp_id"]
        rv = h.expect(rb)["row_ver"]
        out = st.claim_execution(rb, by=SPL, idem_key="claim_execution:%s:%d" % (rb, rv), expect_row_ver=rv,
                                 expect_ver=ver)
        self.assertCode(out, "ok", what="claim_execution(readback)")
        self.assertEqual(h.sink.write({"task_id": task_id}, {"result": "готов", "case_id": cid}), {"ok": True})
        tw = h.clock()
        h.clock.advance(1)
        rv = h.expect(rb)["row_ver"]
        out = st.mark_written(rb, result={"ok": True, "row": None, "written_at": tw}, by=SPL,
                              idem_key="mark_written:%s:%d" % (rb, rv), expect_row_ver=rv)
        self.assertCode(out, "ok", what="mark_written")
        h.clock.advance(1)
        r = h.sink.read({"task_id": task_id})
        self.assertEqual(r["outcome"], "landed")
        ev = {"kind": "readback", "ref": "sink:fake:%s" % task_id, "source": "sink:fake", "written_at": tw,
              "read_at": r["read_at"], "outcome": "landed", "expected": {"result": "готов"}, "got": r.get("value"),
              "target": target}
        out = st.on_readback(rb, evidence=ev, by=SPL, idem_key="on_readback:%s:landed" % rb)
        if check_ok:
            self.assertCode(out, "ok", what="on_readback(landed)")
        return rb, out

    def drive_to_stage5(self, h, st_wa, st_spl, cid, ver=1, task_by=AGENT, q_by=AGENT):
        """Сквозная цепь CONTRACT §14 Д5–Д12: задача → вопрос → пост → ответ адресата → принято (human_mark) →
        выполнено (human_mark) → записано и прочитано назад (landed). Возвращает id для дальнейших шагов."""
        task_id = self.open_task(h, st_wa, cid, ver, by=task_by)
        exp_id, res, m = self.ask_and_post(h, st_wa, st_spl, cid, ver, task_id=task_id, by=q_by)
        self.assertCode(m, "ok", what="mark_post_result(posted)")
        self.assertEqual(h.expect(exp_id)["state"], "waiting")
        topic_mid = self.posted_mid(res, "topic")
        h.clock.advance(60)
        a = self.staff_reply(h, st_spl, "7999", topic_mid, 9001)
        self.assertCode(a, "ok", what="on_staff_answer адресата")
        self.assertEqual(verdict(a), "accepted", dump(a))
        out = st_spl.record_stage(cid, task_id=task_id, stage="task_accepted", evidence=hm("btn:accept:%s" % task_id),
                                  by=APPROVER, idem_key="stage:%s:task_accepted" % task_id)
        self.assertCode(out, "ok", what="ступень 3 human_mark")
        out = st_spl.record_stage(cid, task_id=task_id, stage="physically_done", evidence=hm("btn:done:%s" % task_id),
                                  by=APPROVER, idem_key="stage:%s:physically_done" % task_id)
        self.assertCode(out, "ok", what="ступень 4 human_mark")
        rb, out = self.readback_landed(h, st_spl, cid, task_id, ver)
        t = h.task(task_id)
        self.assertEqual(t["state"], "done", dump(t))
        self.assertEqual(t["top_stage"], 5, dump(t))
        return {"task_id": task_id, "exp_id": exp_id, "rb_id": rb, "topic_mid": topic_mid, "answer": a}

    def propose(self, h, st, cid, task_id, ver=1, intent="readiness_confirmed", by=SPL):
        fact_ids = [f["id"] for f in h.facts(cid) if f["kind"] in ("staff_answer", "readback") and f["state"] == "valid"]
        return st.propose_client_notice(cid, task_id=task_id, intent=intent, fact_ids=fact_ids, by=by,
                                        idem_key="notice:%s:%s:%s:%s" % (cid, ver, task_id, intent), expect_ver=ver)

    def notice_id_of(self, h, out, cid):
        nid = data(out).get("notice_id")
        if not nid:
            nid = h.q("SELECT notice_id FROM rc_notice WHERE case_id=? ORDER BY created_at DESC", (cid,))[0]["notice_id"]
        return nid

    def waive_all(self, h, st, cid, by=APPROVER, skip_roles=()):
        for o in h.obligations(cid):
            if o["state"] in ("open", "unknown") and o["role"] not in skip_roles:
                out = st.settle_obligation(cid, obligation_id=o["id"], by=by,
                                           idem_key="settle:%s:%s" % (o["id"], o["row_ver"]),
                                           expect_row_ver=o["row_ver"],
                                           human={"waive": True, "detail": "синтетика: снято одобряющим"})
                self.assertCode(out, "ok", what="waive %s/%s" % (o["kind"], o["role"]))

    def close_clean(self, h, st, cid, by=APPROVER):
        self.waive_all(h, st, cid, by=by)
        bl = st.blockers(cid)
        self.assertEqual(bl, [], "после снятия обязательств остались блокеры: %s" % dump(bl))
        v = h.ver(cid)
        out = st.close_case(cid, by=by, idem_key="close:%s:%s" % (cid, v), expect_ver=v)
        self.assertCode(out, "ok", what="close_case")
        self.assertEqual(h.case(cid)["state"], "closed")


# =====================================================================================================================
# 00. Полнота: у каждой строки DESIGN §13 есть своя проверка
# =====================================================================================================================


class T00RowIndex(unittest.TestCase):
    def test_every_design_13_row_has_a_test(self):
        """DESIGN §13: «КАЖДАЯ строка — отдельной проверкой»; ключ строки — в имени теста."""
        names = []
        for obj in globals().values():
            if isinstance(obj, type) and issubclass(obj, unittest.TestCase):
                names.extend(n for n in dir(obj) if n.startswith("test_"))
        missing = [row for row, key in ROW_KEYS if not any(key in n for n in names)]
        self.assertEqual(missing, [], "строки §13 без проверки: %s" % missing)


# =====================================================================================================================
# 01. Текущая и будущая бронь того же байка
# =====================================================================================================================


class T01CurrentFutureSameBike(K4Case):
    def test_current_future_same_bike_pick_by_every_purpose(self):
        """§13 «текущая и будущая бронь того же байка»: client/current→текущая, client/future→будущая, handover в
        день брони → бронь, return/debt → текущая; contract по дате; порядок строк не решает (К4-C4, I17; M1, M1b)."""
        p = params_a()
        x = [r_ivan(booking_id="bk-812"), r_boris(booking_id="bk-845")]
        for rows in (x, list(reversed(x))):
            tag = "порядок %s" % [r["row"] for r in rows]
            self.assertPicked(RR.pick(rows, {"purpose": "client", "intent": "current", "contact": wa(IVAN_WA)},
                                      MOMENT, p), 812, "client/current " + tag)
            self.assertPicked(RR.pick(rows, {"purpose": "client", "intent": "future", "contact": wa(BORIS_WA)},
                                      MOMENT, p), 845, "client/future " + tag)
            self.assertPicked(RR.pick(rows, {"purpose": "handover", "plate": "6908"}, F.epoch(2026, 10, 15, 9, 0), p),
                              845, "handover в день брони " + tag)
            for purpose in ("return", "debt"):
                self.assertPicked(RR.pick(rows, {"purpose": purpose, "plate": "6908"}, MOMENT, p), 812,
                                  "%s 09.10 %s" % (purpose, tag))
                self.assertPicked(RR.pick(rows, {"purpose": purpose, "plate": "6908"}, F.epoch(2026, 10, 15, 9, 0),
                                          p), 812, "%s 15.10: бронь Бориса не кандидат %s" % (purpose, tag))
            self.assertPicked(RR.pick(rows, {"purpose": "contract", "contact": wa(BORIS_WA), "plate": "6908",
                                             "contract_date": "2026-10-15"}, MOMENT, p), 845, "contract 15.10 " + tag)
            self.assertPicked(RR.pick(rows, {"purpose": "contract", "contact": wa(IVAN_WA), "plate": "6908",
                                             "contract_date": "2026-10-01"}, MOMENT, p), 812, "contract 01.10 " + tag)
        y = [r_ivan(booking_id="bk-812"), r_ivan_future(booking_id="bk-846")]
        for rows in (y, list(reversed(y))):
            tag = "тот же клиент, порядок %s" % [r["row"] for r in rows]
            self.assertPicked(RR.pick(rows, {"purpose": "client", "intent": "current", "contact": wa(IVAN_WA)},
                                      MOMENT, p), 812, "client/current " + tag)
            self.assertPicked(RR.pick(rows, {"purpose": "client", "intent": "future", "contact": wa(IVAN_WA)},
                                      MOMENT, p), 846, "client/future " + tag)
            self.assertPicked(RR.pick(rows, {"purpose": "client", "intent": "specific", "contact": wa(IVAN_WA),
                                             "booking_id": "bk-846"}, MOMENT, p), 846, "client/specific " + tag)
            self.assertPicked(RR.pick(rows, {"purpose": "contract", "contact": wa(IVAN_WA), "plate": "6908",
                                             "contract_date": "2026-10-16"}, MOMENT, p), 846, "contract 16.10 " + tag)
            r = RR.pick(rows, {"purpose": "client", "intent": None, "contact": wa(IVAN_WA)}, MOMENT, p)
            self.assertEqual(r.get("code"), "unknown", "client/None без смысла — всегда вопрос: %s" % dump(r))
            self.assertAsk(r, "client/None " + tag)
            self.assertGreaterEqual(len(r.get("candidates") or []), 2, dump(r))

    def test_current_future_same_bike_resolve_and_cash_prepay_claimants(self):
        """§13 та же строка на хранилище: resolve по цели; касса «предоплата 6908» без booking_id при текущей аренде
        Ивана и брони Бориса с 15.10 → unknown с обоими претендентами, ничего не записано (К4-C7, К4-C24, I35; M19)."""
        h = self.world(label="r1")
        st = h.store()
        rows = [r_ivan(booking_id="bk-812"), r_boris(booking_id="bk-845")]
        ci = self.ok_case(h, st, rows[0])
        cb = self.ok_case(h, st, rows[1])
        obs = h.clock()
        r = st.resolve(purpose="client", rows=rows, moment=MOMENT, observed_at=obs, intent="future",
                       contact=wa(BORIS_WA))
        self.assertEqual((r.get("code"), r.get("case_id")), ("found", cb), dump(r))
        r = st.resolve(purpose="client", rows=rows, moment=MOMENT, observed_at=obs, intent="current",
                       contact=wa(IVAN_WA))
        self.assertEqual((r.get("code"), r.get("case_id")), ("found", ci), dump(r))
        r = st.resolve(purpose="return", rows=rows, moment=MOMENT, observed_at=obs, plate="6908")
        self.assertEqual((r.get("code"), r.get("case_id")), ("found", ci), dump(r))
        r = st.resolve(purpose="handover", rows=rows, moment=F.epoch(2026, 10, 15, 9, 0), observed_at=obs,
                       plate="6908")
        self.assertEqual((r.get("code"), r.get("case_id")), ("found", cb), dump(r))
        fact, _res = h.cash_fact(2041, 2000, "2026-10-09", description="предоплата 6908")
        self.assertIsNotNone(fact, "фикстура кассы не дала факт: %s" % dump(_res))
        before = h.counts()
        for cid in (ci, cb):
            out = st.bind_cash(cid, cash_fact=fact, rows=rows, source=h.src(name=CASH_SRC, ref="строка 2041"),
                               by=CASH_BY, idem_key=cash_idem(cid, fact))
            self.assertCode(out, "unknown", what="касса без booking_id, два претендента (дело %s)" % cid)
            self.assertAsk(out, "bind_cash")
            cl = data(out).get("claimants")
            if cl is not None:
                self.assertGreaterEqual(len(cl), 2, "претенденты: %s" % dump(out))
        self.assertNoWrites(h, before, "bind_cash unknown")


# =====================================================================================================================
# 02. Висяк и две «в аренде»
# =====================================================================================================================


class T02StaleTwoActive(K4Case):
    def test_stale_two_active_client_stale_and_return_two_active(self):
        """§13 «висяк и две «в аренде»»: висяк 2023 + бронь → unknown(stale_active) с вопросом; две «в аренде» 6908 →
        return/debt unknown(two_active); висяк 2023 + текущая 2026 → return unknown, а не «самая свежая»
        (_rental_for) (К4-C25, I17; M21)."""
        p = params_a()
        stale = F.make_row(row=600, status=F.ST_RENTED, bike=BIKE_NMAX, name="Иван", date_start="2023-05-01 10:00",
                           date_end="2023-05-10 10:00", contacts=IVAN_U, moment=MOMENT)
        fut = r_ivan_future()
        for rows in ([stale, fut], [fut, stale]):
            r = RR.pick(rows, {"purpose": "client", "intent": "current", "contact": wa(IVAN_WA)}, MOMENT, p)
            self.assertEqual(r.get("code"), "unknown", dump(r))
            self.assertEqual(rcode(r), "stale_active", dump(r))
            self.assertAsk(r, "висяк client/current")
        for rows in ([r_anna(), r_petr()], [r_petr(), r_anna()]):
            for purpose in ("return", "debt"):
                r = RR.pick(rows, {"purpose": purpose, "plate": "6908"}, MOMENT, p)
                self.assertEqual(r.get("code"), "unknown", "%s: %s" % (purpose, dump(r)))
                self.assertEqual(rcode(r), "two_active", dump(r))
                self.assertAsk(r, "две «в аренде» %s" % purpose)
                self.assertGreaterEqual(len(r.get("candidates") or []), 2, dump(r))
        for rows in ([stale, r_ivan()], [r_ivan(), stale]):
            r = RR.pick(rows, {"purpose": "return", "plate": "6908"}, MOMENT, p)
            self.assertEqual(r.get("code"), "unknown", "висяк + текущая на возврате: %s" % dump(r))
            self.assertAsk(r, "висяк + текущая return")

    def test_stale_two_active_resolve_on_store(self):
        """Та же строка через Store.resolve (I38): две «в аренде» одного байка у двух дел → unknown, дело не выбрано."""
        h = self.world(label="r2")
        st = h.store()
        rows = [r_anna(booking_id="bk-701"), r_petr(booking_id="bk-702")]
        self.ok_case(h, st, rows[0])
        self.ok_case(h, st, rows[1])
        r = st.resolve(purpose="return", rows=rows, moment=MOMENT, observed_at=h.clock(), plate="6908")
        self.assertEqual(r.get("code"), "unknown", dump(r))
        self.assertIsNone(r.get("case_id"), dump(r))
        self.assertAsk(r, "resolve return две «в аренде»")


# =====================================================================================================================
# 03. Запрос старого договора
# =====================================================================================================================


class T03OldContract(K4Case):
    def test_old_contract_goes_to_past_rental_and_closed_case_add_only(self):
        """§13 «запрос старого договора»: договор 05.09 → аренда 01.09–15.09 (pick client/specific contract_date);
        документ — в дело прошлой аренды (закрытое) добавлением без подъёма и смены состояния; текущая привязка и её
        документы не тронуты; в текущее дело он verified не ложится (I-4, К4-C6; M11)."""
        h = self.world(label="r3")
        st = h.store()
        past, cur = r_done(), r_ivan(booking_id="bk-812")
        r = RR.pick([past, cur], {"purpose": "client", "intent": "specific", "contact": wa(IVAN_WA),
                                  "contract_date": "2026-09-05"}, MOMENT, h.params)
        self.assertPicked(r, 790, "договор 05.09 → прошлая аренда")
        r = RR.pick([cur, past], {"purpose": "client", "intent": "specific", "contact": wa(IVAN_WA),
                                  "contract_date": "2026-09-05"}, MOMENT, h.params)
        self.assertPicked(r, 790, "договор 05.09, обратный порядок строк")
        cp = self.ok_case(h, st, past)
        self.close_clean(h, st, cp)
        ci = self.ok_case(h, st, cur)
        cur_rental = h.rental(ci)
        cur_docs = h.documents(ci)
        h.contract(120, "doc-old-0509", "Иван", "2026-09-05", BIKE_PCX, IVAN_U, "2026-09-05 11:00", "pdf-old-0509")
        cr = h.contract_port.find(number=IVAN_WA, rental=past, phone=IVAN_WA)
        self.assertEqual(cr.get("outcome"), WT.FACT, "фикстура: %s" % dump(cr))
        verp, evp = h.ver(cp), len(h.events(cp))
        out = st.record_document(cp, kind="contract_signed", ext_id="doc-old-0509", status="verified",
                                 source=h.src(name=CONTRACT_SRC, ref="строка 120"), by=CODE,
                                 idem_key="doc:%s:contract_signed:doc-old-0509:2026-09-05 11:00" % cp,
                                 signed_at="2026-09-05 11:00", reg_row=120, rental_id=h.rental(cp)["id"],
                                 contract_result=cr)
        self.assertCode(out, "ok", what="документ в закрытое дело прошлой аренды (добавление)")
        self.assertEqual(h.case(cp)["state"], "closed")
        self.assertEqual(h.ver(cp), verp, "добавление в закрытое дело подняло версию")
        self.assertGreater(len(h.events(cp)), evp, "добавление без события (I5)")
        d = h.doc(h.doc_id(cp, "contract_signed", "doc-old-0509"))
        self.assertEqual((d["status"], d["rental_id"]), ("verified", h.rental(cp)["id"]), dump(d))
        self.assertEqual(h.rental(ci), cur_rental, "текущая привязка тронута")
        self.assertEqual(h.documents(ci), cur_docs, "документы текущего дела тронуты")
        before = h.counts()
        cr_cur = h.contract_port.find(number=IVAN_WA, rental=cur, phone=IVAN_WA)
        out = st.record_document(ci, kind="contract_signed", ext_id="doc-old-0509", status="verified",
                                 source=h.src(name=CONTRACT_SRC, ref="строка 120"), by=CODE,
                                 idem_key="doc:%s:contract_signed:doc-old-0509:x1" % ci, signed_at="2026-09-05 11:00",
                                 reg_row=120, rental_id=h.rental(ci)["id"], contract_result=cr_cur)
        self.assertCode(out, "rejected", what="старый договор против текущей аренды")
        self.assertReasonIn(out, ("doc_conflict", "doc_foreign_rental", "doc_unknown"))
        out = st.record_document(ci, kind="contract_signed", ext_id="doc-old-0509", status="verified",
                                 source=h.src(name=CONTRACT_SRC, ref="строка 120"), by=CODE,
                                 idem_key="doc:%s:contract_signed:doc-old-0509:x2" % ci, signed_at="2026-09-05 11:00",
                                 reg_row=120, rental_id=h.rental(ci)["id"], contract_result=cr)
        self.assertCode(out, "rejected", "doc_foreign_rental", "окно договора ≠ срок привязки текущего дела")
        self.assertNoWrites(h, before, "отказы record_document")

    def test_old_contract_without_case_is_contract_ref_without_verified(self):
        """§13 та же строка: у прошлой аренды дела нет → справочный факт contract_ref в текущем деле, без verified и
        без привязки к текущей аренде; documents_for его показывает в refs как other_rental (I-4, К4-C6)."""
        h = self.world(label="r3b")
        st = h.store()
        ci = self.ok_case(h, st, r_ivan(booking_id="bk-812"))
        docs_before = h.documents(ci)
        val = {"doc_id": "doc-old-0509", "reg_row": 120, "ref_anchor": "4410|2026-09-01|иван",
               "period": ["2026-09-01", "2026-09-15"], "signed_at": "2026-09-05 11:00"}
        fkey = ["contract_ref", "4410|2026-09-01|иван", "doc-old-0509"]
        s = h.src(name=CONTRACT_SRC, ref="строка 120")
        out = st.record_fact(ci, kind="contract_ref", value=val, source=s, scope="case", by=CODE,
                             idem_key="fact:%s:%s:%r" % (ci, json.dumps(fkey, ensure_ascii=False), s["observed_at"]),
                             fkey=fkey)
        self.assertCode(out, "ok", what="contract_ref")
        self.assertEqual(h.documents(ci), docs_before, "contract_ref создал документ дела")
        self.assertEqual(len(h.facts(ci, "contract_ref")), 1)
        r = st.documents_for(ci, period=("2026-09-01", "2026-09-15"))
        self.assertEqual(r.get("code"), "unknown", dump(r))
        self.assertEqual(rcode(r), "doc_unknown", "verified договоров нет → doc_unknown: %s" % dump(r))
        refs = full(r.get("refs"))
        self.assertIn("doc-old-0509", refs, dump(r))
        self.assertIn("other_rental", refs, dump(r))


# =====================================================================================================================
# 04. Договор на будущий период продления (TB-K4-TARGET-PERIOD-0910, TB-K4-DOCUMENT-COVERAGE-0910, I46, К4-C39)
# =====================================================================================================================


class T04ContractExtensionPeriod(K4Case):
    def test_contract_for_extension_period_not_covered_by_initial_signed_pdf(self):
        """§13 «договор на будущий период продления» — К4-C39, I46; мутанты M31, M31b, M31c.

        Дело Ивана (NMAX 6908, 01.10–12.10, без следующей брони того же байка), договор (подпись 01.10) + PDF.
        Отрицательные: (а) записаны verified до продления, затем reconcile_rental → period_changed до 20.10;
        (б) продолжение новой строкой 12.10–20.10 через decide_link(same); (в) ПЕРВОЕ ПОЗДНЕЕ ЧТЕНИЕ: продление до 20.10
        раньше первой записи, bind_contract с арендой 01.10–20.10, verified; (в2) дело открыто сразу по продлённой
        строке; (г) human_binding={"rental_id"} без дат. Во всех: cover_* NULL; documents_for(12.10–20.10) и
        (01.10–12.10) → unknown(doc_period_unknown), missing=["document_period"], ask называет договор от 01.10 и
        период; binding=bound, coverage=unknown, verified; period=None → unknown(period_not_given), missing=["period"],
        coverage=None, pick=None; facts_for_agent ни с каким period не даёт covers; human_binding с ключами покрытия →
        ValueError. Положительные: (д) confirm_document_coverage 01.10–12.10 → found на 01.10–12.10 (PDF тоже covers),
        unknown(doc_period_not_covered) на 12.10–20.10 с вопросом «оформить новый?»; (е) в фикстуре (в) подтверждено
        01.10–20.10 по допсоглашению → found на 12.10–20.10. Отказы подтверждения: не одобряющий → approver_unknown;
        без дат / cover_from > cover_to / без source_ref или act_ref → doc_cover_invalid; иные даты поверх →
        doc_cover_set; unverified / PDF / нет документа → doc_unknown; везде cover_* прежние и записей нет."""
        for name, fn in (("а: продление после записи + д: подтверждено 01.10–12.10", self._c39_a_then_d),
                         ("б: продолжение новой строкой decide_link(same)", self._c39_b),
                         ("в: первое позднее чтение + отказы + е: допсоглашение 01.10–20.10", self._c39_c_then_e),
                         ("в2: дело открыто по продлённой строке", self._c39_c2),
                         ("г: human_binding без дат", self._c39_d)):
            with self.subTest(scenario=name):
                fn()

    # --- фикстура ---
    def _c39_world(self, label, row=None):
        h = self.world(label=label)
        st = h.store()
        row = row or r_ivan(booking_id="bk-812")
        cid = self.ok_case(h, st, row)
        h.contract(233, IVAN_DOC, "Иван", "2026-10-01", BIKE_NMAX, IVAN_U, IVAN_SIGNED, IVAN_PDF)
        return h, st, cid, row

    def _extend(self, h, st, cid, row, new_end="2026-10-20 10:00"):
        ext = with_(row, date_end=new_end)
        out = self.reconcile(h, st, cid, [ext], step=600)
        self.assertCode(out, "ok", what="продление reconcile_rental")
        self.assertEqual(h.rental(cid)["end_day"], new_end[:10], "срок привязки не продлён")
        self.assertTrue(h.events(cid, "period_changed"), "нет события period_changed")
        return ext

    def _record(self, h, st, cid, rental_row, with_pdf=True):
        rid = h.rental(cid)["id"]
        cr = h.contract_port.find(number=IVAN_WA, rental=rental_row, phone=IVAN_WA, bike="6908")
        self.assertEqual(cr.get("outcome"), WT.FACT, "фикстура: bind_contract не дал FACT: %s" % dump(cr))
        self.assertEqual(cr.get("window"), "%s…%s" % (rental_row["date_start"][:10], rental_row["date_end"][:10]))
        out = st.record_document(cid, kind="contract_signed", ext_id=IVAN_DOC, status="verified",
                                 source=h.src(name=CONTRACT_SRC, ref="строка 233"), by=CODE,
                                 idem_key="doc:%s:contract_signed:%s:%s" % (cid, IVAN_DOC, IVAN_SIGNED),
                                 signed_at=IVAN_SIGNED, reg_row=233, rental_id=rid, contract_result=cr)
        self.assertCode(out, "ok", what="record_document(contract_signed, verified)")
        sid = h.doc_id(cid, "contract_signed", IVAN_DOC)
        self.assertIsNotNone(sid)
        pid = None
        if with_pdf:
            pr = h.pdf_port.fetch(IVAN_PDF, allowed={IVAN_PDF})
            self.assertEqual(pr.get("outcome"), WT.FACT, "фикстура PDF: %s" % dump(pr))
            sha = pr["facts"][0]["sha256"]
            out = st.record_document(cid, kind="contract_pdf", ext_id=IVAN_PDF, status="verified",
                                     source=h.src(name=PDF_SRC, ref=IVAN_PDF), by=CODE,
                                     idem_key="doc:%s:contract_pdf:%s:%s" % (cid, IVAN_PDF, sha), sha256=sha,
                                     reg_row=233, rental_id=rid, pdf_result=pr, contract_result=cr)
            self.assertCode(out, "ok", what="record_document(contract_pdf, verified)")
            pid = h.doc_id(cid, "contract_pdf", IVAN_PDF)
            self.assertIsNotNone(pid)
        return sid, pid, rid

    def _assert_period_unknown(self, h, st, cid, doc_ids, label):
        for did in doc_ids:
            d = h.doc(did)
            self.assertEqual(d["status"], "verified", "%s: документ %s не verified: %s" % (label, did, dump(d)))
            for col in COVER_COLS:
                self.assertIsNone(d[col], "%s: %s записан у документа %s (M31b/M31c): %s" % (label, col, did, dump(d)))
        for period in (("2026-10-12", "2026-10-20"), ("2026-10-01", "2026-10-12"), ("2026-10-13", "2026-10-19"),
                       ("2026-10-01", "2026-10-20")):
            r = st.documents_for(cid, period=period)
            what = "%s: documents_for%s" % (label, period)
            self.assertEqual(r.get("code"), "unknown", "%s → не unknown (M31): %s" % (what, dump(r)))
            self.assertEqual(rcode(r), "doc_period_unknown", "%s: %s" % (what, dump(r)))
            self.assertEqual(r.get("missing"), ["document_period"], "%s: %s" % (what, dump(r)))
            self.assertIsNone(r.get("pick"), "%s: %s" % (what, dump(r)))
            ask = r.get("ask") or ""
            for part in ("01.10", dm(period[0]), dm(period[1])):
                self.assertIn(part, ask, "%s: ask не называет %s: %r" % (what, part, ask))
            docs = dict((x.get("document_id"), x) for x in r.get("documents") or [])
            for did in doc_ids:
                self.assertIn(did, docs, "%s: документа %s нет в ответе: %s" % (what, did, dump(r)))
                x = docs[did]
                self.assertEqual(x.get("binding"), "bound", "%s: %s" % (what, dump(x)))
                self.assertEqual(x.get("coverage"), "unknown", "%s: %s" % (what, dump(x)))
                self.assertEqual(x.get("status"), "verified", "%s: %s" % (what, dump(x)))
                self.assertIsNone(x.get("cover_from"), "%s: %s" % (what, dump(x)))
                self.assertIsNone(x.get("cover_to"), "%s: %s" % (what, dump(x)))
        for period in (None, ("2026-10-12", None), (None, "2026-10-20")):
            r = st.documents_for(cid, period=period)
            what = "%s: documents_for(period=%r)" % (label, period)
            self.assertEqual(r.get("code"), "unknown", "%s: %s" % (what, dump(r)))
            self.assertEqual(rcode(r), "period_not_given", "%s: %s" % (what, dump(r)))
            self.assertEqual(r.get("missing"), ["period"], "%s: %s" % (what, dump(r)))
            self.assertIsNone(r.get("pick"), "%s: %s" % (what, dump(r)))
            self.assertTrue((r.get("ask") or "").strip(), "%s: ask пуст" % what)
            docs = dict((x.get("document_id"), x) for x in r.get("documents") or [])
            for did in doc_ids:
                self.assertIn(did, docs, "%s: %s" % (what, dump(r)))
                self.assertEqual(docs[did].get("binding"), "bound", "%s: %s" % (what, dump(docs[did])))
                self.assertIsNone(docs[did].get("coverage"), "%s: покрытие без периода (M31c): %s"
                                  % (what, dump(docs[did])))
        for period in (None, ("2026-10-01", "2026-10-12"), ("2026-10-12", "2026-10-20")):
            f = st.facts_for_agent(cid, period=period)
            for fact in f.get("facts") or []:
                if fact.get("kind") == "case_document" and fact.get("doc_kind") in ("contract_signed", "contract_pdf"):
                    self.assertNotEqual(fact.get("coverage"), "covers", "%s: агенту отдано covers при period=%r: %s"
                                        % (label, period, dump(fact)))
                    self.assertIsNone(fact.get("cover_from"), dump(fact))
                    self.assertIsNone(fact.get("cover_to"), dump(fact))
                    if period is None:
                        self.assertIsNone(fact.get("coverage"), "%s: без period coverage=null: %s"
                                          % (label, dump(fact)))

    def _confirm(self, st, cid, did, cfrom, cto, source_ref, act_ref, by=APPROVER, idem=None):
        return st.confirm_document_coverage(cid, document_id=did, cover_from=cfrom, cover_to=cto,
                                            source_ref=source_ref, act_ref=act_ref, by=by,
                                            idem_key=idem or "cover:%s:%s:%s" % (did, cfrom, cto))

    # --- сценарии ---
    def _c39_a_then_d(self):
        h, st, cid, row = self._c39_world("c39a")
        sid, pid, rid1 = self._record(h, st, cid, row)
        self._extend(h, st, cid, row)
        for did in (sid, pid):
            d = h.doc(did)
            self.assertEqual((d["status"], d["rental_id"]), ("verified", rid1),
                             "продление сменило статус/rental_id документа: %s" % dump(d))
        self._assert_period_unknown(h, st, cid, [sid, pid], "(а)")
        # (д) отдельно подтверждённое покрытие первоначального срока
        ver0, ev0 = h.ver(cid), len(h.events(cid))
        src_ref = "PDF договора: срок аренды 01.10–12.10"
        out = self._confirm(st, cid, sid, "2026-10-01", "2026-10-12", src_ref, "btn:cover:1")
        self.assertCode(out, "ok", what="(д) confirm_document_coverage одобряющим")
        self.assertEqual(h.ver(cid), ver0, "(д) подтверждение покрытия подняло версию")
        self.assertTrue(h.events(cid, "document_coverage_confirmed"), "(д) нет события document_coverage_confirmed")
        d = h.doc(sid)
        self.assertEqual((d["cover_from"], d["cover_to"], d["cover_basis"], d["cover_ref"], d["cover_by"],
                          d["cover_act"]),
                         ("2026-10-01", "2026-10-12", "human_confirmed", src_ref, 1001, "btn:cover:1"), dump(d))
        self.assertIsNotNone(d["cover_at"])
        p = h.doc(pid)
        for col in COVER_COLS:
            self.assertIsNone(p[col], "(д) у PDF покрытие записано копией (наследуется при чтении): %s" % dump(p))
        for period in (("2026-10-01", "2026-10-12"), ("2026-10-03", "2026-10-05")):
            r = st.documents_for(cid, period=period)
            self.assertEqual(r.get("code"), "found", "(д) documents_for%s: %s" % (period, dump(r)))
            self.assertEqual(r.get("pick"), sid, dump(r))
            docs = dict((x.get("document_id"), x) for x in r.get("documents") or [])
            self.assertEqual(docs[sid].get("coverage"), "covers", dump(r))
            self.assertEqual(docs[pid].get("coverage"), "covers", "(д) PDF наследует покрытие договора: %s" % dump(r))
        r = st.documents_for(cid, period=("2026-10-12", "2026-10-20"))
        self.assertEqual(r.get("code"), "unknown", dump(r))
        self.assertEqual(rcode(r), "doc_period_not_covered", dump(r))
        self.assertEqual(r.get("missing"), ["document_period"], dump(r))
        self.assertIsNone(r.get("pick"), dump(r))
        ask = r.get("ask") or ""
        self.assertIn("оформить нов", ask.lower(), "(д) вопрос «оформить новый?»: %r" % ask)
        self.assertIn("12.10", ask)
        self.assertIn("20.10", ask)
        docs = dict((x.get("document_id"), x) for x in r.get("documents") or [])
        self.assertEqual(docs[sid].get("coverage"), "not_covers", dump(r))
        self.assertEqual(docs[sid].get("status"), "verified", dump(r))
        f = st.facts_for_agent(cid, period=("2026-10-01", "2026-10-12"))
        cov = [x.get("coverage") for x in f.get("facts") or []
               if x.get("kind") == "case_document" and x.get("doc_kind") == "contract_signed"]
        self.assertIn("covers", cov, "(д) агенту при found покрытие covers: %s" % dump(f))
        f = st.facts_for_agent(cid, period=("2026-10-12", "2026-10-20"))
        for x in f.get("facts") or []:
            if x.get("kind") == "case_document":
                self.assertNotEqual(x.get("coverage"), "covers", dump(x))
        self.assertTrue((f.get("reason") or "").strip(), "(д) reason агента несёт вопрос: %s" % dump(f))
        before, d_before = h.counts(), h.doc(sid)
        out = self._confirm(st, cid, sid, "2026-10-01", "2026-10-12", src_ref, "btn:cover:1")
        self.assertCode(out, "duplicate", what="(д) повтор тех же дат")
        out = self._confirm(st, cid, sid, "2026-10-01", "2026-10-20", "допсоглашение: 01.10–20.10", "btn:cover:2")
        self.assertCode(out, "rejected", "doc_cover_set", "(д) иные даты поверх записанных")
        self.assertNoWrites(h, before, "(д) повтор/doc_cover_set")
        self.assertEqual(h.doc(sid), d_before)

    def _c39_b(self):
        h, st, cid, row = self._c39_world("c39b")
        sid, pid, rid1 = self._record(h, st, cid, row)
        cases0 = h.counts()["rc_case"]
        new = r_ivan_future(row=901, date_start="2026-10-12 10:00", date_end="2026-10-20 10:00", booking_id="bk-901")
        out = h.open_case(st, new, origin="intake", by=SPL)
        self.assertCode(out, "unknown", "possible_continuation", "(б) продление новой строкой")
        self.assertEqual(data(out).get("case_id"), cid, dump(out))
        exp_id = data(out).get("exp_id")
        self.assertTrue(exp_id, dump(out))
        self.assertEqual(h.counts()["rc_case"], cases0, "(б) второе дело открыто")
        v = h.ver(cid)
        out = st.decide_link(exp_id, decision="same", by=APPROVER, idem_key="link:%s:same" % exp_id, expect_ver=v,
                             row=new, source=h.src(ref="строка 901"))
        self.assertCode(out, "ok", what="(б) decide_link(same)")
        self.assertEqual(h.counts()["rc_case"], cases0)
        cur = h.rental(cid)
        self.assertEqual((cur["start_day"], cur["end_day"]), ("2026-10-12", "2026-10-20"), dump(cur))
        for did in (sid, pid):
            d = h.doc(did)
            self.assertEqual((d["status"], d["rental_id"]), ("verified", rid1), dump(d))
        self._assert_period_unknown(h, st, cid, [sid, pid], "(б)")

    def _c39_c_then_e(self):
        h, st, cid, row = self._c39_world("c39c")
        ext = self._extend(h, st, cid, row)
        sid, pid, rid2 = self._record(h, st, cid, ext)
        self.assertEqual(h.doc(sid)["rental_id"], h.rental(cid)["id"])
        self._assert_period_unknown(h, st, cid, [sid, pid], "(в)")
        out = st.record_document(cid, kind="contract_signed", ext_id="doc-ivan-unv", status="unverified",
                                 source=h.src(name=CONTRACT_SRC, ref="строка 240"), by=CODE,
                                 idem_key="doc:%s:contract_signed:doc-ivan-unv:2026-10-02 09:00" % cid,
                                 signed_at="2026-10-02 09:00", reg_row=240)
        self.assertCode(out, "ok", what="(в) запись unverified договора")
        uid = h.doc_id(cid, "contract_signed", "doc-ivan-unv")
        good = dict(document_id=sid, cover_from="2026-10-01", cover_to="2026-10-20",
                    source_ref="допсоглашение №1 к договору doc-ivan-0110, п.2: срок аренды 01.10–20.10",
                    act_ref="btn:cover:7", by=APPROVER)
        refusals = (
            ("не одобряющий человек", {"by": HUMAN_NOT_APPROVER}, "approver_unknown"),
            ("агент", {"by": AGENT}, "approver_unknown"),
            ("код", {"by": CODE}, "approver_unknown"),
            ("без дат", {"cover_from": "", "cover_to": ""}, "doc_cover_invalid"),
            ("без cover_to", {"cover_to": ""}, "doc_cover_invalid"),
            ("cover_from > cover_to", {"cover_from": "2026-10-20", "cover_to": "2026-10-01"}, "doc_cover_invalid"),
            ("даты не YYYY-MM-DD", {"cover_from": "01.10.2026", "cover_to": "20.10.2026"}, "doc_cover_invalid"),
            ("без source_ref", {"source_ref": ""}, "doc_cover_invalid"),
            ("без act_ref", {"act_ref": ""}, "doc_cover_invalid"),
            ("unverified договор", {"document_id": uid}, "doc_unknown"),
            ("PDF, а не contract_signed", {"document_id": pid}, "doc_unknown"),
            ("нет такого документа", {"document_id": 987654}, "doc_unknown"),
        )
        before, d_before = h.counts(), h.doc(sid)
        for i, (label, over, reason) in enumerate(refusals):
            kw = dict(good)
            kw.update(over)
            out = st.confirm_document_coverage(cid, idem_key="cover:%s:%s:%s#refusal-%d" % (
                kw["document_id"], kw["cover_from"], kw["cover_to"], i), **kw)
            self.assertCode(out, "rejected", reason, "отказ подтверждения: %s" % label)
            self.assertNoWrites(h, before, "отказ подтверждения: %s" % label)
            self.assertEqual(h.doc(sid), d_before, "отказ подтверждения изменил документ: %s" % label)
        r = st.documents_for(cid, period=("2026-10-12", "2026-10-20"))
        self.assertEqual((r.get("code"), rcode(r)), ("unknown", "doc_period_unknown"), "после отказов: %s" % dump(r))
        # (е) подтверждение одобряющим по допсоглашению
        out = st.confirm_document_coverage(cid, idem_key="cover:%s:2026-10-01:2026-10-20" % sid, **good)
        self.assertCode(out, "ok", what="(е) подтверждение 01.10–20.10")
        d = h.doc(sid)
        self.assertEqual((d["cover_from"], d["cover_to"], d["cover_basis"], d["cover_ref"], d["cover_by"]),
                         ("2026-10-01", "2026-10-20", "human_confirmed", good["source_ref"], 1001), dump(d))
        for period in (("2026-10-12", "2026-10-20"), ("2026-10-01", "2026-10-20")):
            r = st.documents_for(cid, period=period)
            self.assertEqual(r.get("code"), "found", "(е) documents_for%s: %s" % (period, dump(r)))
            self.assertEqual(r.get("pick"), sid, dump(r))
            docs = dict((x.get("document_id"), x) for x in r.get("documents") or [])
            self.assertEqual(docs[pid].get("coverage"), "covers", dump(r))
            self.assertEqual(docs[uid].get("binding"), "unknown", "(е) unverified — принадлежность unknown: %s"
                             % dump(docs[uid]))
            self.assertNotEqual(docs[uid].get("coverage"), "covers", dump(docs[uid]))
        r = st.documents_for(cid, period=("2026-10-15", "2026-10-25"))
        self.assertEqual((r.get("code"), rcode(r)), ("unknown", "doc_period_not_covered"), dump(r))
        before, d_before = h.counts(), h.doc(sid)
        out = st.confirm_document_coverage(cid, idem_key="cover:%s:2026-10-01:2026-10-20" % sid, **good)
        self.assertCode(out, "duplicate", what="(е) повтор")
        kw = dict(good, cover_to="2026-10-25", act_ref="btn:cover:8")
        out = st.confirm_document_coverage(cid, idem_key="cover:%s:2026-10-01:2026-10-25" % sid, **kw)
        self.assertCode(out, "rejected", "doc_cover_set", "(е) иные даты поверх записанных")
        self.assertNoWrites(h, before, "(е) повтор/doc_cover_set")
        self.assertEqual(h.doc(sid), d_before)

    def _c39_c2(self):
        h, st, cid, row = self._c39_world("c39c2", row=r_ivan(booking_id="bk-812", date_end="2026-10-20 10:00"))
        sid, pid, _rid = self._record(h, st, cid, row)
