class T05AmbiguousChoice(K4Case):
    def test_ambiguous_choice_every_unknown_has_missing_and_ask(self):
        """§13 «неоднозначный выбор»: свойство по фикстурам — каждый unknown pick/resolve/bind_cash/reconcile_rental/
        open_case/documents_for несёт непустые missing и ask (К4-C5, I12; M12)."""
        p = params_a()
        got = []
        stale = F.make_row(row=600, status=F.ST_RENTED, bike=BIKE_NMAX, name="Иван", date_start="2023-05-01 10:00",
                           date_end="2023-05-10 10:00", contacts=IVAN_U, moment=MOMENT)
        picks = (
            ("client/None", [r_ivan(), r_ivan_future()], {"purpose": "client", "intent": None, "contact": wa(IVAN_WA)},
             MOMENT),
            ("висяк client/current", [stale, r_ivan_future()],
             {"purpose": "client", "intent": "current", "contact": wa(IVAN_WA)}, MOMENT),
            ("две в аренде", [r_anna(), r_petr()], {"purpose": "return", "plate": "6908"}, MOMENT),
            ("будущей нет", [r_ivan()], {"purpose": "client", "intent": "future", "contact": wa(IVAN_WA)}, MOMENT),
            ("текущей нет, есть бронь", [r_boris()], {"purpose": "client", "intent": "current",
                                                     "contact": wa(BORIS_WA)}, MOMENT),
            ("выдача не в день брони", [r_boris()], {"purpose": "handover", "plate": "6908"},
             F.epoch(2026, 10, 16, 9, 0)),
            ("договор вне периодов", [r_ivan(), r_ivan_future()],
             {"purpose": "client", "intent": "specific", "contact": wa(IVAN_WA), "contract_date": "2026-10-14"},
             MOMENT),
        )
        for label, rows, q, m in picks:
            r = RR.pick(rows, q, m, p)
            self.assertEqual(r.get("code"), "unknown", "%s: %s" % (label, dump(r)))
            got.append(("pick " + label, r))
        h = self.world(label="r5")
        st = h.store()
        ivan, boris, ivan_f = r_ivan(booking_id="bk-812"), r_boris(booking_id="bk-845"), r_ivan_future(row=847)
        ci = self.ok_case(h, st, ivan)
        self.ok_case(h, st, boris)
        r = st.resolve(purpose="client", rows=[ivan, ivan_f, boris], moment=MOMENT, observed_at=h.clock(),
                       intent=None, contact=wa(IVAN_WA))
        self.assertEqual(r.get("code"), "unknown", dump(r))
        got.append(("resolve client/None", r))
        fact, _ = h.cash_fact(2041, 2000, "2026-10-09", description="предоплата 6908")
        out = st.bind_cash(ci, cash_fact=fact, rows=[ivan, boris], source=h.src(name=CASH_SRC, ref="строка 2041"),
                           by=CASH_BY, idem_key=cash_idem(ci, fact))
        self.assertEqual(out.get("code"), "unknown", dump(out))
        got.append(("bind_cash", out))
        out = self.reconcile(h, st, ci, [with_(ivan, date_end="2026-10-17 10:00"), boris])
        self.assertEqual(out.get("code"), "unknown", dump(out))
        got.append(("reconcile продление поверх брони", out))
        swap = F.make_row(row=850, status=F.ST_BOOKED, bike=BIKE_PCX, name="Иван", date_start="2026-10-05 10:00",
                          date_end="2026-10-12 10:00", contacts=IVAN_U, booking_id="bk-850", moment=MOMENT)
        h2 = self.world(label="r5b")
        st2 = h2.store()
        self.ok_case(h2, st2, ivan)
        out = h2.open_case(st2, swap, origin="intake", by=SPL)
        self.assertEqual(out.get("code"), "unknown", dump(out))
        got.append(("open_case продолжение", out))
        for period in (None, ("2026-10-12", "2026-10-20")):
            r = st.documents_for(ci, period=period)
            self.assertEqual(r.get("code"), "unknown", dump(r))
            got.append(("documents_for %r" % (period,), r))
        for label, out in got:
            self.assertAsk(out, label)
            self.assertTrue(rcode(out), "%s: reason пуст: %s" % (label, dump(out)))


