class T06PeriodChange(K4Case):
    def test_period_change_bumps_keeps_case_id_and_history(self):
        """§13 «изменение срока»: period_changed + подъём; тот же case_id; две привязки в истории; событие с автором,
        источником и ссылкой (К4-C1, К4-C3, I4; M10)."""
        h = self.world(label="r6")
        st = h.store()
        row = r_ivan(booking_id="bk-812")
        ci = self.ok_case(h, st, row)
        cases0 = h.counts()["rc_case"]
        out = self.reconcile(h, st, ci, [with_(row, date_end="2026-10-14 10:00")])
        self.assertCode(out, "ok", what="продление на месте")
        self.assertEqual(h.ver(ci), 2, "подъём ровно на 1")
        self.assertEqual(h.counts()["rc_case"], cases0, "новое дело при смене срока (M10)")
        rs = h.rentals(ci)
        self.assertEqual(len(rs), 2, dump(rs))
        self.assertEqual([r["current"] for r in rs], [0, 1], dump(rs))
        self.assertEqual((rs[0]["end_day"], rs[1]["end_day"]), ("2026-10-12", "2026-10-14"))
        ev = h.events(ci, "period_changed")
        self.assertTrue(ev, "нет period_changed")
        for e in ev:
            self.assertTrue(e["author"] and e["source"] and e["ref"], "событие без автора/источника/ссылки: %s"
                            % dump(e))
        vb = h.events(ci, "version_bumped")
        self.assertEqual(len(vb), 1, dump(vb))
        self.assertIn("period_changed", vb[0]["payload"])
        cv = st.case_view(ci)
        self.assertTrue((cv.get("rental") or {}).get("history"), "история привязок пуста: %s" % dump(cv.get("rental")))

    def test_period_change_over_next_booking_attention_both_no_bump(self):
        """§13 та же строка: продление поверх брони Бориса → unknown(which_rental), link_state=ambiguous, внимание у
        обоих дел, без подъёма, привязка прежняя (I-21, К4-C33)."""
        h = self.world(label="r6b")
        st = h.store()
        ivan, boris = r_ivan(booking_id="bk-812"), r_boris(booking_id="bk-845")
        ci = self.ok_case(h, st, ivan)
        cb = self.ok_case(h, st, boris)
        out = self.reconcile(h, st, ci, [with_(ivan, date_end="2026-10-17 10:00"), boris])
        self.assertCode(out, "unknown", "which_rental", "продление поверх брони")
        self.assertAsk(out, "which_rental")
        c, b = h.case(ci), h.case(cb)
        self.assertEqual((c["ver"], c["link_state"], c["attention"]), (1, "ambiguous", 1), dump(c))
        self.assertEqual((b["ver"], b["attention"]), (1, 1), dump(b))
        self.assertEqual(h.rental(ci)["end_day"], "2026-10-12", "привязка сменилась при конфликте")
        self.assertEqual(h.events(ci, "version_bumped"), [])


