class T07BikeSwap(K4Case):
    def _swap_row(self, **kw):
        base = dict(row=850, status=F.ST_BOOKED, bike=BIKE_PCX, name="Иван", date_start="2026-10-05 10:00",
                    date_end="2026-10-12 10:00", contacts=IVAN_U, booking_id="bk-850", moment=MOMENT)
        base.update(kw)
        return F.make_row(**base)

    def test_bike_swap_in_place_with_booking_id(self):
        """§13 «подмена байка» на месте с booking_id → bike_changed + подъём; один case_id; в истории оба байка
        (К4-C1, К4-C3; M10)."""
        h = self.world(label="r7a")
        st = h.store()
        row = r_ivan(booking_id="bk-812")
        ci = self.ok_case(h, st, row)
        cases0 = h.counts()["rc_case"]
        out = self.reconcile(h, st, ci, [with_(row, bike=BIKE_PCX)])
        self.assertCode(out, "ok", what="подмена на месте")
        self.assertEqual(h.ver(ci), 2)
        self.assertEqual(h.rental(ci)["plate"], "4410")
        self.assertEqual(h.counts()["rc_case"], cases0)
        self.assertTrue(h.events(ci, "bike_changed"))
        bike = full(st.case_view(ci).get("bike"))
        self.assertIn("6908", bike, "история байков: %s" % bike)
        self.assertIn("4410", bike)

    def test_bike_swap_new_row_intake_continuation_then_decide_same(self):
        """§13 подмена новой строкой (intake) → unknown(possible_continuation) + confirm_link у прежнего дела, второго
        дела нет, resolve строки → unknown(link_confirmation); decide_link(same) → одно дело с обоими байками (I34,
        К4-C23; M25)."""
        h = self.world(label="r7b")
        st = h.store()
        ivan = r_ivan(booking_id="bk-812")
        ci = self.ok_case(h, st, ivan)
        cases0 = h.counts()["rc_case"]
        new = self._swap_row()
        out = h.open_case(st, new, origin="intake", by=SPL)
        self.assertCode(out, "unknown", "possible_continuation", "подмена новой строкой")
        self.assertAsk(out, "possible_continuation")
        self.assertEqual(data(out).get("case_id"), ci, dump(out))
        exp_id = data(out).get("exp_id")
        self.assertEqual(h.expect(exp_id)["kind"], "confirm_link")
        self.assertEqual(h.counts()["rc_case"], cases0, "второе дело (M25)")
        r = st.resolve(purpose="handover", rows=[ivan, new], moment=MOMENT, observed_at=h.clock(), row=new)
        self.assertEqual((r.get("code"), rcode(r)), ("unknown", "link_confirmation"), dump(r))
        v = h.ver(ci)
        out = st.decide_link(exp_id, decision="same", by=APPROVER, idem_key="link:%s:same" % exp_id, expect_ver=v,
                             row=new, source=h.src(ref="строка 850"))
        self.assertCode(out, "ok", what="decide_link(same)")
        self.assertEqual(h.ver(ci), v + 1)
        self.assertEqual(h.counts()["rc_case"], cases0)
        cur = h.rental(ci)
        self.assertEqual((cur["plate"], cur["booking_id"]), ("4410", "bk-850"), dump(cur))
        self.assertEqual(h.expect(exp_id)["state"], "answered")
        link = h.one("SELECT * FROM rc_link WHERE kind='booking_id' AND value='bk-850' AND status='confirmed'")
        self.assertEqual((link or {}).get("case_id"), ci, dump(link))
        bike = full(st.case_view(ci).get("bike"))
        self.assertIn("6908", bike)
        self.assertIn("4410", bike)
        r = st.resolve(purpose="handover", rows=[ivan, new], moment=MOMENT, observed_at=h.clock(), row=new)
        self.assertEqual((r.get("code"), r.get("case_id")), ("found", ci), dump(r))

    def test_bike_swap_extension_new_row_touching_return_day_is_question(self):
        """§13 продление новой строкой, касание днём возврата при CONTINUATION_GAP_DAYS=UNKNOWN →
        unknown(possible_continuation) с param_unknown:CONTINUATION_GAP_DAYS — вопрос, не склейка и не второе дело;
        decide_link(same) → одно дело (К4-C23)."""
        h = self.world(label="r7c")
        st = h.store()
        ivan = r_ivan(booking_id="bk-812")
        ci = self.ok_case(h, st, ivan)
        cases0 = h.counts()["rc_case"]
        new = self._swap_row(row=851, bike=BIKE_NMAX, date_start="2026-10-12 10:00", date_end="2026-10-20 10:00",
                             booking_id="bk-851")
        out = h.open_case(st, new, origin="intake", by=SPL)
        self.assertCode(out, "unknown", "possible_continuation", "касание днём возврата")
        trail = full(out) + full(h.expects(ci)) + full(h.events(ci)) + full(h.events(None, "case_opened"))
        self.assertIn("CONTINUATION_GAP_DAYS", trail, "причина вопроса не названа (param_unknown:CONTINUATION_GAP_DAYS)")
        self.assertEqual(h.counts()["rc_case"], cases0)
        exp_id = data(out)["exp_id"]
        out = st.decide_link(exp_id, decision="same", by=APPROVER, idem_key="link:%s:same" % exp_id,
                             expect_ver=h.ver(ci), row=new, source=h.src(ref="строка 851"))
        self.assertCode(out, "ok", what="decide_link(same) продления")
        cur = h.rental(ci)
        self.assertEqual((cur["start_day"], cur["end_day"]), ("2026-10-12", "2026-10-20"), dump(cur))
        self.assertEqual(h.counts()["rc_case"], cases0)

    def test_bike_swap_gap_two_days_is_new_case_with_near_cases(self):
        """§13 / CONTRACT §6 continuation: разрыв ≥ 1 сутки — не кандидат; новое дело несёт near_cases (не окно
        выбора)."""
        h = self.world(label="r7d")
        st = h.store()
        ci = self.ok_case(h, st, r_ivan(booking_id="bk-812"))
        new = self._swap_row(row=852, bike=BIKE_NMAX, date_start="2026-10-14 10:00", date_end="2026-10-20 10:00",
                             booking_id="bk-852")
        out = h.open_case(st, new, origin="intake", by=SPL)
        self.assertCode(out, "ok", what="разрыв 2 суток")
        cn = out.get("case_id") or data(out).get("case_id")
        self.assertNotEqual(cn, ci)
        self.assertIn(ci, data(out).get("near_cases") or [], dump(out))

    def test_bike_swap_without_booking_id_needs_confirm_link_once(self):
        """§13 подмена без booking_id → drift → unknown(link_confirmation) + ОДНО ожидание confirm_link; автоподъёма
        нет; повторное чтение того же смещения второго confirm_link не плодит (I-12, К4-C33)."""
        h = self.world(label="r7e")
        st = h.store()
        ivan = r_ivan()
        ci = self.ok_case(h, st, ivan)
        moved = with_(ivan, bike=BIKE_PCX)
        out = self.reconcile(h, st, ci, [moved])
        self.assertCode(out, "unknown", "link_confirmation", "подмена без booking_id")
        self.assertAsk(out, "drift")
        c = h.case(ci)
        self.assertEqual((c["link_state"], c["ver"]), ("drift", 1), dump(c))
        self.assertEqual(h.rental(ci)["plate"], "6908", "привязка сменилась без подтверждения")
        cl = [e for e in h.expects(ci, "confirm_link") if e["state"] not in ("answered", "superseded", "cancelled")]
        self.assertEqual(len(cl), 1, dump(cl))
        out = self.reconcile(h, st, ci, [moved])
        self.assertEqual(out.get("code"), "unknown", dump(out))
        cl2 = [e for e in h.expects(ci, "confirm_link") if e["state"] not in ("answered", "superseded", "cancelled")]
        self.assertEqual(len(cl2), 1, "confirm_link расплодился: %s" % dump(cl2))
        self.assertEqual(h.ver(ci), 1)


