class T08ContactChange(K4Case):
    def test_contact_change_crm_added_then_superseded_same_case(self):
        """§13 «смена контакта»: contact_added(crm), затем прежний номер superseded; один case_id, два контакта;
        клиент по superseded-номеру → none(contact_superseded), по новому → то же дело (I36, К4-C1; M10b)."""
        h = self.world(label="r8")
        st = h.store()
        row = r_ivan(booking_id="bk-812")
        ci = self.ok_case(h, st, row)
        cases0 = h.counts()["rc_case"]
        two = with_(row, contacts="%s, %s" % (IVAN_U, IVAN_NEW_U))
        out = self.reconcile(h, st, ci, [two])
        self.assertCode(out, "ok", what="новый номер в U")
        self.assertTrue(h.events(ci, "contact_added"))
        one = with_(row, contacts=IVAN_NEW_U)
        out = self.reconcile(h, st, ci, [one])
        self.assertCode(out, "ok", what="прежний номер пропал из U")
        self.assertTrue(h.events(ci, "contact_superseded"))
        cs = dict((c["value"], c) for c in h.contacts(ci) if c["channel"] == "wa")
        self.assertEqual(cs[IVAN_WA]["status"], "superseded", dump(cs))
        self.assertEqual(cs[IVAN_NEW_WA]["status"], "active", dump(cs))
        self.assertEqual(cs[IVAN_NEW_WA]["source_kind"], "crm", dump(cs))
        self.assertEqual(h.ver(ci), 1, "контакт поднял версию")
        self.assertEqual(h.counts()["rc_case"], cases0)
        r = st.resolve(purpose="client", rows=[one], moment=MOMENT, observed_at=h.clock(), intent="current",
                       contact=wa(IVAN_NEW_WA))
        self.assertEqual((r.get("code"), r.get("case_id")), ("found", ci), dump(r))
        r = st.resolve(purpose="client", rows=[one], moment=MOMENT, observed_at=h.clock(), intent="current",
                       contact=wa(IVAN_WA))
        self.assertIn(r.get("code"), ("none", "unknown"), "старый номер по свежему листу: %s" % dump(r))
        self.assertIsNone(r.get("case_id"), "старый номер нашёл дело: %s" % dump(r))
        r = st.resolve(purpose="client", rows=[two], moment=MOMENT, observed_at=h.clock(), intent="current",
                       contact=wa(IVAN_WA))
        self.assertEqual((r.get("code"), rcode(r)), ("none", "contact_superseded"),
                         "старый номер по устаревшему снимку, где он ещё в U (M10b): %s" % dump(r))
        self.assertIsNone(r.get("case_id"), dump(r))

    def test_contact_change_add_contact_only_crm_or_approver(self):
        """§13 та же строка: добавить контакт может только crm (сверка) или одобряющий; агент, код и не одобряющий →
        rejected(contact_source), записей нет (I36)."""
        h = self.world(label="r8b")
        st = h.store()
        ci = self.ok_case(h, st, r_ivan(booking_id="bk-812"))
        before = h.counts()
        for by in (AGENT, CODE, HUMAN_NOT_APPROVER):
            s = h.src(name="wa-agent", ref="wa:in:9", method="event")
            out = st.add_contact(ci, channel="wa", value="66810000001", by=by, source=s,
                                 idem_key="contact:%s:wa:66810000001:wa:in:9:%s" % (ci, by["kind"]))
            self.assertCode(out, "rejected", "contact_source", "add_contact от %s" % by["kind"])
        self.assertNoWrites(h, before, "отказы add_contact")
        out = st.add_contact(ci, channel="wa", value="66810000001", by=APPROVER,
                             source=h.src(name="решение одобряющего", ref="btn:contact:1", method="human"),
                             idem_key="contact:%s:wa:66810000001:btn:contact:1" % ci)
        self.assertCode(out, "ok", what="add_contact одобряющим")
        c = [x for x in h.contacts(ci) if x["value"] == "66810000001"]
        self.assertEqual((len(c), c[0]["status"]), (1, "active"), dump(c))


