class T09ForeignPaymentDocumentAnswer(K4Case):
    def test_foreign_payment_document_answer_cash_by_one_field(self):
        """§13 «чужая оплата»: касса с booking_id брони Бориса в день аренды Анны → unknown у обоих; касса без
        booking_id в день передачи (конец Анны = начало Бориса) → unknown(which_rental); booking_id чужой строки от
        модели → unknown(contact); ничего не записано (К4-C7, К4-C24, I18, I35; M2, M22)."""
        h = self.world(label="r9")
        st = h.store()
        anna, boris = r_anna(booking_id="bk-701", date_end="2026-10-15 10:00"), r_boris(booking_id="bk-845")
        ca = self.ok_case(h, st, anna)
        cb = self.ok_case(h, st, boris)
        rows = [anna, boris]
        f1, _ = h.cash_fact(2051, 1500, "2026-10-05", booking_id="bk-845")
        self.assertIsNotNone(f1)
        f2, _ = h.cash_fact(2052, 1500, "2026-10-15")
        self.assertIsNotNone(f2)
        before = h.counts()
        for cid, fact, label in ((ca, f1, "booking_id Бориса в день Анны → дело Анны"),
                                 (cb, f1, "booking_id Бориса до начала его брони"),
                                 (ca, f2, "день передачи, дело Анны"), (cb, f2, "день передачи, дело Бориса")):
            out = st.bind_cash(cid, cash_fact=fact, rows=rows, source=h.src(name=CASH_SRC, ref="строка %s"
                                                                            % fact["row"]),
                               by=CASH_BY, idem_key=cash_idem(cid, fact))
            self.assertCode(out, "unknown", what=label)
            self.assertAsk(out, label)
        self.assertNoWrites(h, before, "касса одним полем")
        r = st.resolve(purpose="client", rows=rows, moment=MOMENT, observed_at=h.clock(), intent="specific",
                       contact=wa(ANNA_WA), booking_id="bk-845")
        self.assertEqual((r.get("code"), rcode(r)), ("unknown", "contact"), dump(r))
        self.assertIsNone(r.get("case_id"))

    def test_foreign_payment_document_answer_contract_one_field(self):
        """§13 «чужой документ»: договор, совпавший с делом только байком (телефон другой), только телефоном (байк
        другой) или хвостом номера с чужим кодом страны → rejected(doc_conflict), документов не прибавилось;
        rental_id/окно чужого дела → rejected(doc_foreign_rental) (I-4, I18, К4-C6; M11b)."""
        h = self.world(label="r9b")
        st = h.store()
        anna, boris = r_anna(booking_id="bk-701"), r_boris(booking_id="bk-845")
        ca = self.ok_case(h, st, anna)
        cb = self.ok_case(h, st, boris)
        rid_a, rid_b = h.rental(ca)["id"], h.rental(cb)["id"]
        before = h.counts()
        variants = (
            ("только байк (телефон другой)", ("+66 81 000 0000", BIKE_NMAX), dict(phone="", bike="6908")),
            ("только телефон (байк другой)", (ANNA_U, BIKE_PCX), dict(phone=ANNA_WA)),
            ("хвост номера, чужой код страны", ("+7 855 512 345", BIKE_NMAX), dict(phone=ANNA_WA)),
        )
        for i, (label, (phone, bike), q) in enumerate(variants):
            h.contract(300 + i, "doc-x-%d" % i, "Анна", "2026-10-02", bike, phone, "2026-10-02 10:00")
            cr = h.contract_port.find(number=ANNA_WA, rental=anna, **q)
            self.assertEqual(cr.get("outcome"), WT.CONFLICT, "фикстура %s: %s" % (label, dump(cr)))
            out = st.record_document(ca, kind="contract_signed", ext_id="doc-x-%d" % i, status="verified",
                                     source=h.src(name=CONTRACT_SRC, ref="строка %d" % (300 + i)), by=CODE,
                                     idem_key="doc:%s:contract_signed:doc-x-%d:2026-10-02 10:00" % (ca, i),
                                     signed_at="2026-10-02 10:00", reg_row=300 + i, rental_id=rid_a,
                                     contract_result=cr)
            self.assertCode(out, "rejected", "doc_conflict", "договор %s" % label)
        h.contract(320, "doc-boris", "Борис", "2026-10-15", BIKE_NMAX, BORIS_U, "2026-10-15 09:00")
        cr_b = h.contract_port.find(number=BORIS_WA, rental=boris, phone=BORIS_WA)
        self.assertEqual(cr_b.get("outcome"), WT.FACT, dump(cr_b))
        for rid, label in ((rid_a, "окно брони Бориса ≠ срок аренды Анны"), (rid_b, "rental_id дела Бориса")):
            out = st.record_document(ca, kind="contract_signed", ext_id="doc-boris", status="verified",
                                     source=h.src(name=CONTRACT_SRC, ref="строка 320"), by=CODE,
                                     idem_key="doc:%s:contract_signed:doc-boris:%s" % (ca, rid), signed_at=None,
                                     reg_row=320, rental_id=rid, contract_result=cr_b)
            self.assertCode(out, "rejected", "doc_foreign_rental", label)
        self.assertNoWrites(h, before, "чужие договоры")

    def test_foreign_payment_document_answer_reply_not_addressee_or_foreign_topic(self):
        """§13 «чужой ответ»: реплай не адресата поста, в чужой теме, ник без id, адресат другого места → справка,
        ожидание не продвинуто, ступени 2 нет; адресат в своей теме — accepted (К4-C9, I9; M9)."""
        h = self.world(label="r9c")
        st = h.store()
        ca = self.ok_case(h, st, r_anna(booking_id="bk-701"))
        tid = self.open_task(h, st, ca, 1)
        exp_id, res, m = self.ask_and_post(h, st, st, ca, 1, task_id=tid)
        self.assertCode(m, "ok")
        mid = self.posted_mid(res, "topic")
        posts = h.posts(exp_id)
        topic_post = [p for p in posts if p["place"] == "topic"][0]
        self.assertEqual(topic_post["topic_bike"], "6908", "topic_bike пуст у места topic: %s" % dump(posts))
        cases = (
            ("не адресат", dict(msg_id="7101", author_id=9999), "reference_foreign_author"),
            ("чужая тема", dict(msg_id="7102", author_id=9001, thread_id="56"), "reference_foreign_place"),
            ("ник без id", dict(msg_id="7103", author_id=None, username="staff9001"), "reference_foreign_author"),
            ("адресат Delivery на посту темы", dict(msg_id="7104", author_id=9002), "reference_foreign_author"),
        )
        for label, kw, want in cases:
            h.clock.advance(10)
            out = self.staff_reply(h, st, reply_to=mid, **kw)
            self.assertCode(out, "ok", what=label)
            self.assertEqual(verdict(out), want, "%s: %s" % (label, dump(out)))
            self.assertEqual(h.expect(exp_id)["state"], "waiting", label)
            self.assertNotIn("answer_received", h.stages(tid), label)
        self.assertEqual(sorted(a["verdict"] for a in h.answers(exp_id)),
                         sorted(v for _l, _k, v in cases), "справки не сохранены с вердиктом")
        out = self.staff_reply(h, st, "7105", mid, 9001)
        self.assertEqual(verdict(out), "accepted", dump(out))
        self.assertIn("answer_received", h.stages(tid))


# =====================================================================================================================
# 10. Рестарт между вопросом, ответом, подтверждением и записью
# =====================================================================================================================


class T10RestartBetween(K4Case):
    def test_restart_between_question_and_answer_no_repost(self):
        """§13 «рестарт…»: новый Store между шагами — всё на диске; recover ничего не меняет; постов у подделки один
        набор; ответ после рестарта принимается (К4-C12, I15; M4)."""
        h = self.world(label="r10a")
        st = h.store("splinter")
        ci = self.ok_case(h, st, r_ivan(booking_id="bk-812"))
        exp_id, res, m = self.ask_and_post(h, st, st, ci, 1)
        sent = len(h.telegram.sent)
        st2 = h.restart("splinter")
        out = st2.recover(by=SPL)
        self.assertCode(out, "ok", what="recover без захватов")
        self.assertEqual(h.expect(exp_id)["state"], "waiting")
        got = st2.claim_for_posting(by=SPL)
        self.assertEqual([e for e in got or [] if e.get("exp_id") == exp_id], [])
        self.assertEqual(len(h.telegram.sent), sent, "повторный пост после рестарта")
        out = self.staff_reply(h, st2, "7200", self.posted_mid(res, "topic"), 9001)
        self.assertEqual(verdict(out), "accepted", dump(out))

    def test_restart_between_claim_and_post_result_flight_unknown_without_repost(self):
        """§13: обрыв после claim_for_posting → recover() своей роли → flight_unknown, автоматического повтора нет;
        главное событие recovered (case_id NULL) пишется; пост, найденный позже, принимается из flight_unknown той же
        ролью (I15, I29, К4-C12; M4)."""
        h = self.world(label="r10b")
        st = h.store("splinter")
        ci = self.ok_case(h, st, r_ivan(booking_id="bk-812"))
        out = self.request_q(st, ci, 1)
        exp_id = data(out)["exp_id"]
        exp = self.claim_one(h, st, exp_id, ("staff_question",))
        res = F.run_coro(h.staff_port.post(exp))                         # пост ушёл, а исход потерян обрывом
        attempts = len(h.telegram.attempts)
        st2 = h.restart("splinter")
        out = st2.recover(by=SPL)
        self.assertCode(out, "ok", what="recover")
        self.assertGreaterEqual(int(data(out).get("expect") or 0), 1, dump(out))
        self.assertEqual(h.expect(exp_id)["state"], "flight_unknown")
        rec = [e for e in h.events() if e["type"] == "recovered"]
        self.assertTrue(rec and rec[-1]["case_id"] is None, "главное событие recovered: %s" % dump(rec))
        got = st2.claim_for_posting(by=SPL)
        self.assertEqual([e for e in got or [] if e.get("exp_id") == exp_id], [], "flight_unknown отдан в повтор")
        self.assertEqual(len(h.telegram.attempts), attempts)
        self.assertTrue(any(s.get("exp_id") == exp_id for s in st2.stuck() or []), "flight_unknown не виден в stuck()")
        out = self.mark(h, st2, exp_id, res)
        self.assertCode(out, "ok", what="mark_post_result(posted) из flight_unknown")
        self.assertEqual(h.expect(exp_id)["state"], "waiting")

    def test_restart_between_approval_and_bridge_readback_not_reexecuted(self):
        """§13: «да» → claim_execution → мост вызван → обрыв до mark_written → recover() → pending_checks(role) отдаёт
        readback → чтение назад; мост повторно не зовут, claim_execution второй раз не проходит (I15, I28, К4-C12,
        К4-C29; M4)."""
        h = self.world(label="r10c")
        st = h.store("splinter")
        ci = self.ok_case(h, st, r_ivan(booking_id="bk-812"))
        exp_id, card_mid = self.card(h, st, ci, 1, "activate")
        out = self.yes(h, st, "8100", card_mid)
        self.assertCode(out, "ok", what="«да» на карточку активации")
        self.assertEqual((verdict(out), data(out).get("execute")), ("accepted", True), dump(out))
        rb = data(out).get("readback_exp_id")
        self.assertTrue(rb, dump(out))
        self.assertEqual(h.expect(rb)["state"], "planned")
        rv = h.expect(rb)["row_ver"]
        out = st.claim_execution(rb, by=SPL, idem_key="claim_execution:%s:%d" % (rb, rv), expect_row_ver=rv,
                                 expect_ver=1)
        self.assertCode(out, "ok", what="claim_execution")
        h.bridge.activate_booking(row=812, booking_id="bk-812")
        st2 = h.restart("splinter")
        out = st2.recover(by=SPL)
        self.assertCode(out, "ok")
        self.assertEqual(h.expect(rb)["state"], "flight_unknown")
        pend = st2.pending_checks(role="splinter")
        mine = [p for p in pend or [] if p.get("exp_id") == rb]
        self.assertEqual(len(mine), 1, "pending_checks не отдал readback: %s" % dump(pend))
        self.assertEqual(mine[0].get("what"), "readback")
        h.crm.plan = [{"outcome": "landed", "row": 812, "status": "В аренде"}]
        rs = h.crm.row_status(target=mine[0].get("target") or {})
        ev = {"kind": "readback", "ref": "строка 812", "source": "crm", "written_at": h.expect(rb)["claim_at"],
              "read_at": rs["read_at"], "outcome": "landed", "expected": "В аренде", "got": rs["status"],
              "row": 812, "siblings": rs["siblings"]}
        out = st2.on_readback(rb, evidence=ev, by=SPL, idem_key="on_readback:%s:landed" % rb)
        self.assertCode(out, "ok", what="on_readback после рестарта")
        self.assertEqual(h.expect(rb)["state"], "answered")
        rv = h.expect(rb)["row_ver"]
        out = st2.claim_execution(rb, by=SPL, idem_key="claim_execution:%s:%d" % (rb, rv), expect_row_ver=rv,
                                  expect_ver=1)
        self.assertNotEqual(out.get("code"), "ok", "исполнение повторно захвачено: %s" % dump(out))
        self.assertEqual(h.counters.bridge_red_calls, 1, "мост позван повторно")
        self.assertEqual([p for p in st2.pending_checks(role="splinter") or [] if p.get("exp_id") == rb], [])

    def test_restart_between_notice_intent_and_draft_yields_one_draft(self):
        """§13: намерение → claim_notice → черновик WA → обрыв до mark_notice → recover → pending_checks(role) →
        NoticePort.find → drafted; черновик один, propose один (I42, К4-C12, К4-C29)."""
        h = self.world(label="r10d")
        wa_st, spl = h.store("wa"), h.store("splinter")
        cb = self.ok_case(h, spl, r_boris(booking_id="bk-845"))
        d = self.drive_to_stage5(h, wa_st, spl, cb)
        out = self.propose(h, wa_st, cb, d["task_id"])
        self.assertCode(out, "ok", what="propose_client_notice")
        nid = self.notice_id_of(h, out, cb)
        self.assertEqual(h.notice_row(nid)["state"], "intent")
        rv = h.notice_row(nid)["row_ver"]
        out = wa_st.claim_notice(nid, by=WA_CORE, idem_key="nclaim:%s:%d" % (nid, rv), expect_row_ver=rv)
        self.assertCode(out, "ok", what="claim_notice")
        self.assertEqual(h.notice_row(nid)["state"], "drafting")
        r = h.notice.propose(notice_id=nid, case_id=cb, case_ver=1, intent="readiness_confirmed", facts=[])
        draft_id = r["draft_id"]
        wa2 = h.restart("wa")
        out = wa2.recover(by=WA_CORE)
        self.assertCode(out, "ok")
        self.assertEqual(int(data(out).get("notice") or 0), 1, dump(out))
        self.assertEqual(h.notice_row(nid)["state"], "draft_unknown")
        pend = wa2.pending_checks(role="wa")
        self.assertTrue([p for p in pend or [] if p.get("notice_id") == nid], dump(pend))
        f = h.notice.find(nid)
        self.assertEqual(f.get("draft_id"), draft_id)
        rv = h.notice_row(nid)["row_ver"]
        out = wa2.mark_notice(nid, state="drafted", by=WA_CORE, idem_key="nst:%s:drafted:%s" % (nid, draft_id),
                              expect_row_ver=rv, draft_id=draft_id)
        self.assertCode(out, "ok", what="mark_notice(drafted) после сверки")
        self.assertEqual(h.notice_row(nid)["state"], "drafted")
        self.assertEqual(len(h.notice.drafts), 1)
        self.assertEqual(len([c for c in h.notice.calls if c[0] == "propose"]), 1)
        rv = h.notice_row(nid)["row_ver"]
        out = wa2.claim_notice(nid, by=WA_CORE, idem_key="nclaim:%s:%d" % (nid, rv), expect_row_ver=rv)
        self.assertNotEqual(out.get("code"), "ok", "второй захват намерения: %s" % dump(out))
        self.assertEqual(h.counters.client_sends, 0)

    def test_restart_between_two_roles_does_not_break_each_other(self):
        """§13: два Store разных ролей на одном файле; рестарт одного трогает только СВОИ захваты (I29, К4-C29; M17)."""
        h = self.world(label="r10e")
