# 11. Повтор события
# =====================================================================================================================


class T11RepeatEvent(K4Case):
    def test_repeat_event_duplicate_and_payload_mismatch_conflict(self):
        """§13 «повтор события»: тот же idem_key и содержимое → duplicate с event_seq первого раза, записей нет; тот же
        ключ с другим содержимым → conflict(idem_payload_mismatch); ответ (chat, msg_id) второй раз → duplicate
        (I7, I32, К4-C13; M7, M20)."""
        h = self.world(label="r11")
        st = h.store()
        row = r_ivan(booking_id="bk-812")
        s = h.src(ref="строка 812")
        first = st.open_case(origin="test", by=CODE, idem_key="open:test:bk:bk-812", booking_id="bk-812",
                             rental_row=row, contacts=[], source=s)
        self.assertCode(first, "ok")
        ci = first.get("case_id") or data(first)["case_id"]
        before = h.counts()
        again = st.open_case(origin="test", by=CODE, idem_key="open:test:bk:bk-812", booking_id="bk-812",
                             rental_row=row, contacts=[], source=s)
        self.assertCode(again, "duplicate", what="повтор open_case")
        self.assertEqual(again.get("event_seq"), first.get("event_seq"), dump(again))
        self.assertNoWrites(h, before, "duplicate open_case")
        fk = ["bike_event", "6908", "km", "ev-1"]
        s2 = h.src(name="лист «события»", ref="ev-1", method="door")
        key = "fact:%s:%s:%r" % (ci, json.dumps(fk), s2["observed_at"])
        out = st.record_fact(ci, kind="bike_event", value={"type": "km", "km": 1200}, source=s2, scope="case",
                             by=CODE, idem_key=key, fkey=fk)
        self.assertCode(out, "ok")
        before = h.counts()
        out = st.record_fact(ci, kind="bike_event", value={"type": "km", "km": 1200}, source=s2, scope="case",
                             by=CODE, idem_key=key, fkey=fk)
        self.assertCode(out, "duplicate", what="повтор record_fact")
        out = st.record_fact(ci, kind="bike_event", value={"type": "km", "km": 9999}, source=s2, scope="case",
                             by=CODE, idem_key=key, fkey=fk)
        self.assertCode(out, "conflict", "idem_payload_mismatch", "тот же ключ, другое содержимое")
        self.assertNoWrites(h, before, "duplicate/conflict record_fact")
        out = st.bump_version(ci, reason="new_request", ref="wa:in:1", by=APPROVER,
                              idem_key="bump:%s:1:new_request:wa:in:1" % ci, expect_ver=1)
        self.assertCode(out, "ok")
        before = h.counts()
        out = st.bump_version(ci, reason="new_request", ref="wa:in:1", by=APPROVER,
                              idem_key="bump:%s:1:new_request:wa:in:1" % ci, expect_ver=1)
        self.assertCode(out, "duplicate", what="повтор bump_version")
        self.assertEqual(h.ver(ci), 2)
        self.assertNoWrites(h, before, "duplicate bump")

    def test_repeat_event_same_reply_and_same_cash_row(self):
        """§13: один и тот же реплай (chat, msg_id) и одна строка кассы второй раз — duplicate, второй записи нет."""
        h = self.world(label="r11b")
        st = h.store()
        ci = self.ok_case(h, st, r_ivan(booking_id="bk-812"))
        exp_id, res, m = self.ask_and_post(h, st, st, ci, 1)
        mid = self.posted_mid(res, "topic")
        a1 = self.staff_reply(h, st, "7300", mid, 9001)
        self.assertEqual(verdict(a1), "accepted", dump(a1))
        before = h.counts()
        a2 = self.staff_reply(h, st, "7300", mid, 9001)
        self.assertCode(a2, "duplicate", what="тот же реплай")
        self.assertNoWrites(h, before, "duplicate ответа")
        fact, _ = h.cash_fact(2061, 11000, "2026-10-02", booking_id="bk-812")
        rows = [r_ivan(booking_id="bk-812")]
        out = st.bind_cash(ci, cash_fact=fact, rows=rows, source=h.src(name=CASH_SRC, ref="строка 2061"),
                           by=CASH_BY, idem_key=cash_idem(ci, fact))
        self.assertCode(out, "ok")
        before = h.counts()
        out = st.bind_cash(ci, cash_fact=fact, rows=rows, source=h.src(name=CASH_SRC, ref="строка 2061"),
                           by=CASH_BY, idem_key=cash_idem(ci, fact))
        self.assertIn(out.get("code"), ("duplicate", "ok"), dump(out))
        self.assertNoWrites(h, before, "повтор той же строки кассы")


