class T12CompetingWrite(K4Case):
    def test_competing_write_two_stores_one_ok_other_conflict(self):
        """§13 «конкурирующая запись»: два Store с одной expect_ver — один ok, второй conflict с expected/current_ver;
        событие подъёма одно (I8, К4-C14; M8)."""
        h = self.world(label="r12")
        a, b = h.store("wa"), h.store("splinter")
        ci = self.ok_case(h, a, r_ivan(booking_id="bk-812"))
        o1 = a.bump_version(ci, reason="new_request", ref="wa:in:10", by=APPROVER,
                            idem_key="bump:%s:1:new_request:wa:in:10" % ci, expect_ver=1)
        o2 = b.bump_version(ci, reason="new_request", ref="tg:20", by=APPROVER,
                            idem_key="bump:%s:1:new_request:tg:20" % ci, expect_ver=1)
        self.assertCode(o1, "ok")
        self.assertCode(o2, "conflict", what="второй писатель с прежней версией")
        self.assertEqual((o2.get("expected_ver"), o2.get("current_ver")), (1, 2), dump(o2))
        self.assertEqual(h.ver(ci), 2)
        self.assertEqual(len(h.events(ci, "version_bumped")), 1)

    def test_competing_write_one_store_two_threads(self):
        """§13: один объект Store из двух потоков — без ProgrammingError (соединение на поток, §5.6)."""
        h = self.world(label="r12b")
        st = h.store()
        ci = self.ok_case(h, st, r_ivan(booking_id="bk-812"))
        errors, outs = [], []

        def work(n):
            try:
                for i in range(5):
                    fk = ["bike_event", "6908", "km", "t%d-%d" % (n, i)]
                    s = {"name": "лист «события»", "ref": "t%d-%d" % (n, i), "method": "door",
                         "read_at": MOMENT + n * 10 + i, "observed_at": MOMENT + n * 10 + i}
                    outs.append(st.record_fact(ci, kind="bike_event", value={"type": "km", "n": n, "i": i},
                                               source=s, scope="case", by=CODE,
                                               idem_key="fact:%s:%s:%r" % (ci, json.dumps(fk), s["observed_at"]),
                                               fkey=fk))
                    st.case_view(ci)
            except Exception as e:                                       # noqa: BLE001
                errors.append("%s: %s" % (type(e).__name__, e))

        threads = [threading.Thread(target=work, args=(n,)) for n in (1, 2)]
        for t in threads:
            t.start()
        for t in threads:
            t.join(60)
        self.assertEqual(errors, [], "ошибки потоков: %s" % errors)
        self.assertEqual(sorted(o.get("code") for o in outs), ["ok"] * 10, dump(outs))
        self.assertEqual(len(h.facts(ci, "bike_event")), 10)

    def test_competing_write_blockers_computed_inside_close_transaction(self):
        """§13: блокеры прочитаны (пусто), второй писатель вставляет обязательство, close_case первого →
        rejected(blockers) — предусловия считаются в транзакции записи (I13, I31, К4-C31; M5)."""
        h = self.world(label="r12c")
        a, b = h.store("splinter"), h.store("human")
        cp = self.ok_case(h, a, r_done())
        self.waive_all(h, a, cp)
        self.assertEqual(a.blockers(cp), [])
        out = b.open_obligation(cp, kind="money", role="delivery", direction="from_client",
                                source=h.src(name="решение одобряющего", ref="btn:obl:1", method="human"),
                                by=APPROVER, idem_key="obl:%s:money:delivery:btn:obl:1" % cp, amount=200,
                                currency="THB", outcome="valid")
        self.assertCode(out, "ok", what="вставка обязательства вторым писателем")
        v = h.ver(cp)
        out = a.close_case(cp, by=APPROVER, idem_key="close:%s:%s" % (cp, v), expect_ver=v)
        self.assertCode(out, "rejected", "blockers", "close_case по устаревшему чтению блокеров")
        self.assertTrue(data(out).get("blockers"), dump(out))
        self.assertEqual(h.case(cp)["state"], "open")

    def test_competing_write_lock_held_longer_than_timeout_is_store_busy(self):
        """§13: замок базы дольше busy_timeout → unknown(store_busy, missing=["retry"]), записей нет; повтор тем же
        idem_key после снятия замка — ok (I33, I43, К4-C31)."""
        h = self.world(label="r12d")
        st = h.store()
        ci = self.ok_case(h, st, r_ivan(booking_id="bk-812"))
        busy = h.other_store("human", busy_timeout_s=0.3)
        before = h.counts()
        lock = sqlite3.connect(h.path, timeout=10, isolation_level=None)
        try:
            lock.execute("BEGIN IMMEDIATE")
            out = busy.bump_version(ci, reason="new_request", ref="wa:in:30", by=APPROVER,
                                    idem_key="bump:%s:1:new_request:wa:in:30" % ci, expect_ver=1)
            self.assertCode(out, "unknown", "store_busy", "запись при чужом замке")
            self.assertEqual(out.get("missing"), ["retry"], dump(out))
        finally:
            lock.execute("COMMIT")
            lock.close()
        self.assertNoWrites(h, before, "store_busy")
        out = busy.bump_version(ci, reason="new_request", ref="wa:in:30", by=APPROVER,
                                idem_key="bump:%s:1:new_request:wa:in:30" % ci, expect_ver=1)
        self.assertCode(out, "ok", what="повтор после снятия замка")


