# 13. Старое чтение после нового
# =====================================================================================================================


class T13OldReadAfterNew(K4Case):
    def test_old_read_after_new_is_stale_read_nothing_changes(self):
        """§13 «старое чтение после нового»: снимок 11:45 после чтения 12:00 → ok(stale_read), ничего не изменено;
        новое чтение применяется, следующее старое — снова stale_read; для фактов одного fkey то же (I30, К4-C30; M18).
        observed_at — время нашего чтения, не версия листа (§8.4)."""
        h = self.world(label="r13")
        st = h.store()
        row = r_ivan(booking_id="bk-812")
        ci = self.ok_case(h, st, row, observed_at=F.epoch(2026, 10, 9, 12, 0))
        before = h.counts()
        out = self.reconcile(h, st, ci, [with_(row, date_end="2026-10-14 10:00")],
                             observed_at=F.epoch(2026, 10, 9, 11, 45))
        self.assertCode(out, "ok", what="старое чтение")
        self.assertTrue(data(out).get("stale_read"), dump(out))
        self.assertNoWrites(h, before, "stale_read")
        self.assertEqual(h.rental(ci)["end_day"], "2026-10-12")
        out = self.reconcile(h, st, ci, [with_(row, date_end="2026-10-14 10:00")],
                             observed_at=F.epoch(2026, 10, 9, 12, 10))
        self.assertCode(out, "ok")
        self.assertEqual(h.rental(ci)["end_day"], "2026-10-14")
        before = h.counts()
        out = self.reconcile(h, st, ci, [row], observed_at=F.epoch(2026, 10, 9, 12, 5))
        self.assertCode(out, "ok")
        self.assertTrue(data(out).get("stale_read"), dump(out))
        self.assertEqual(h.rental(ci)["end_day"], "2026-10-14", "откат срока старым чтением (M18)")
        self.assertNoWrites(h, before, "второй stale_read")
        fk = ["bike_state", BIKE_NMAX, "2026-10-09 11:00"]
        val = {"status": "в аренде", "location": "", "updated": "2026-10-09 11:00"}
        s_new = h.src(name=STATE_SRC, ref=BIKE_NMAX, observed_at=F.epoch(2026, 10, 9, 12, 0))
        out = st.record_fact(ci, kind="bike_state", value=val, source=s_new, scope="case", by=CODE,
                             idem_key="fact:%s:%s:%r" % (ci, json.dumps(fk, ensure_ascii=False),
                                                         s_new["observed_at"]), fkey=fk)
        self.assertCode(out, "ok")
        before = h.counts()
        s_old = h.src(name=STATE_SRC, ref=BIKE_NMAX, observed_at=F.epoch(2026, 10, 9, 11, 30))
        out = st.record_fact(ci, kind="bike_state", value=dict(val, status="дома"), source=s_old, scope="case",
                             by=CODE, idem_key="fact:%s:%s:%r" % (ci, json.dumps(fk, ensure_ascii=False),
                                                                 s_old["observed_at"]), fkey=fk)
        self.assertCode(out, "ok")
        self.assertTrue(data(out).get("stale_read"), dump(out))
        self.assertNoWrites(h, before, "stale_read факта")


