class T14LateAnswerPrevVersion(K4Case):
    def test_late_answer_prev_version_superseded_reference_no_stage(self):
        """§13 «поздний ответ к прежней версии»: подъём → ожидание superseded, вопрос — в staff_qids_to_close; ответ
        адресата → справка (reference_superseded/stale_version), ступени нет, execute нет (К4-C8; M3)."""
        h = self.world(label="r14")
        st = h.store()
        ci = self.ok_case(h, st, r_ivan(booking_id="bk-812"))
        tid = self.open_task(h, st, ci, 1)
        exp_id, res, m = self.ask_and_post(h, st, st, ci, 1, task_id=tid)
        qid = h.expect(exp_id)["ext_qid"]
        out = st.bump_version(ci, reason="new_request", ref="wa:in:2", by=APPROVER,
                              idem_key="bump:%s:1:new_request:wa:in:2" % ci, expect_ver=1)
        self.assertCode(out, "ok")
        self.assertIn(exp_id, data(out).get("superseded") or [], dump(out))
        if qid:
            self.assertIn(qid, data(out).get("staff_qids_to_close") or [], dump(out))
        self.assertEqual(h.expect(exp_id)["state"], "superseded")
        a = self.staff_reply(h, st, "7400", self.posted_mid(res, "topic"), 9001)
        self.assertCode(a, "ok")
        self.assertIn(verdict(a), ("reference_superseded", "reference_stale_version"), dump(a))
        self.assertEqual(h.expect(exp_id)["state"], "superseded")
        self.assertNotIn("answer_received", h.stages(tid))

    def test_late_answer_prev_version_post_during_bump_is_recorded(self):
        """§13: пост, ушедший во время подъёма (ожидание in_flight → superseded), записан в rc_post без смены
        состояния; ответ на него — справка (I40)."""
        h = self.world(label="r14b")
        st = h.store("splinter")
        ci = self.ok_case(h, st, r_ivan(booking_id="bk-812"))
        out = self.request_q(st, ci, 1)
        exp_id = data(out)["exp_id"]
        exp = self.claim_one(h, st, exp_id, ("staff_question",))
        rv_claim = h.expect(exp_id)["row_ver"]
        res = F.run_coro(h.staff_port.post(exp))
        out = st.bump_version(ci, reason="new_request", ref="wa:in:3", by=APPROVER,
                              idem_key="bump:%s:1:new_request:wa:in:3" % ci, expect_ver=1)
        self.assertCode(out, "ok")
        self.assertEqual(h.expect(exp_id)["state"], "superseded")
        out = self.mark(h, st, exp_id, res, expect_row_ver=rv_claim)
        if out.get("code") == "conflict":                               # CAS по row_ver захвата устарел подъёмом
            out = self.mark(h, st, exp_id, res)
        self.assertCode(out, "ok", what="mark_post_result(posted) для superseded")
        self.assertEqual(h.expect(exp_id)["state"], "superseded")
        self.assertTrue(h.posts(exp_id), "пост во время подъёма потерян (I40)")
        a = self.staff_reply(h, st, "7401", self.posted_mid(res, "topic"), 9001)
        self.assertEqual(verdict(a), "reference_superseded", dump(a))

    def test_late_answer_prev_version_stale_version_verdict(self):
        """§13 / §4.7 п.8 (M3): ожидание ещё waiting, а версия дела впереди → reference_stale_version, ожидание не
        продвинуто, ступени нет. Через API такой рассинхрон не возникает (подъём отзывает ожидания), поэтому он
        моделируется прямой правкой rc_case.ver в ОДНОРАЗОВОЙ базе теста (схема CONTRACT §2), а вердикт судит Store."""
        h = self.world(label="r14c")
        st = h.store()
        ci = self.ok_case(h, st, r_ivan(booking_id="bk-812"))
        tid = self.open_task(h, st, ci, 1)
        exp_id, res, m = self.ask_and_post(h, st, st, ci, 1, task_id=tid)
        con = sqlite3.connect(h.path, timeout=10, isolation_level=None)
        try:
            con.execute("UPDATE rc_case SET ver = ver + 1 WHERE case_id = ?", (ci,))
        finally:
            con.close()
        a = self.staff_reply(h, st, "7402", self.posted_mid(res, "topic"), 9001)
        self.assertCode(a, "ok")
        self.assertEqual(verdict(a), "reference_stale_version", "версия ответа не сверена (M3): %s"
                         % dump(a))
        self.assertEqual(h.expect(exp_id)["state"], "waiting")
        self.assertNotIn("answer_received", h.stages(tid))


