# 15. Вмешательство человека
# =====================================================================================================================


class T15HumanIntervention(K4Case):
    def test_human_intervention_blocks_notice_until_approver_clears(self):
        """§13 «вмешательство человека»: пауза WA → внимание во ВСЕХ открытых делах номера; propose_client_notice →
        rejected(attention); clear_attention кодом → rejected; одобряющий с чужим wa_pause_no → pause_mismatch; со своим
        — ok, намерение проходит (I24, К4-C21; M13)."""
        h = self.world(label="r15")
        wa_st, spl = h.store("wa"), h.store("splinter")
        cb = self.ok_case(h, spl, r_boris(booking_id="bk-845"))
        d = self.drive_to_stage5(h, wa_st, spl, cb)
        out = wa_st.on_human_intervention(contact=wa(BORIS_WA), kind="text", channel="wa", ref="wa:echo:77",
                                          at=h.clock(), wa_pause_no=3, by=WA_CORE, idem_key="human:wa:wa:echo:77")
        self.assertCode(out, "ok", what="вмешательство с паузой WA")
        self.assertIn(cb, data(out).get("cases") or [], dump(out))
        c = h.case(cb)
        self.assertEqual((c["attention"], c["wa_pause_no"]), (1, 3), dump(c))
        before = h.counts()
        out = self.propose(h, wa_st, cb, d["task_id"])
        self.assertCode(out, "rejected", "attention", "намерение при внимании")
        self.assertNoWrites(h, before, "rejected(attention)")
        for by in (CODE, AGENT, HUMAN_NOT_APPROVER):
            out = wa_st.clear_attention(cb, by=by, idem_key="clear:%s:%s:%s" % (cb, c["pause_no"], by["kind"]),
                                        wa_pause_no=3)
            self.assertCode(out, "rejected", what="снятие внимания %s" % by["name"])
        out = wa_st.clear_attention(cb, by=APPROVER, idem_key="clear:%s:%s:x" % (cb, c["pause_no"]), wa_pause_no=4)
        self.assertCode(out, "rejected", "pause_mismatch", "чужой номер паузы")
        self.assertEqual(h.case(cb)["attention"], 1)
        out = wa_st.clear_attention(cb, by=APPROVER, idem_key="clear:%s:%s" % (cb, c["pause_no"]), wa_pause_no=3)
        self.assertCode(out, "ok", what="снятие одобряющим со своим номером паузы")
        self.assertEqual(h.case(cb)["attention"], 0)
        out = self.propose(h, wa_st, cb, d["task_id"])
        self.assertCode(out, "ok", what="намерение после снятия внимания")

    def test_human_intervention_all_cases_of_number_media_and_tg(self):
        """§13: вмешательство пишется во все открытые дела номера; фото эхом WA без паузы — событие без внимания; текст
        на канале ≠ wa — внимание при NON_WA_MEDIA_EXEMPT=UNKNOWN; второе вмешательство номер не меняет (I24,
        К4-C21; M28)."""
        h = self.world(label="r15b")
        st = h.store("wa")
        ci = self.ok_case(h, st, r_ivan(booking_id="bk-812"))
        cf = self.ok_case(h, st, r_ivan_future(booking_id="bk-846"))
        ev0 = len(h.events())
        out = st.on_human_intervention(contact=wa(IVAN_WA), kind="image", channel="wa", ref="wa:echo:1",
                                       at=h.clock(), wa_pause_no=None, by=WA_CORE, idem_key="human:wa:wa:echo:1")
        self.assertCode(out, "ok", what="фото эхом WA без паузы")
        self.assertEqual((h.case(ci)["attention"], h.case(cf)["attention"]), (0, 0))
        self.assertGreater(len(h.events()), ev0, "вмешательство без события")
        out = st.on_human_intervention(contact=wa(IVAN_WA), kind="text", channel="tg", ref="tg:msg:5",
                                       at=h.clock(), wa_pause_no=None, by=WA_CORE, idem_key="human:tg:tg:msg:5")
        self.assertCode(out, "ok", what="текст в TG")
        self.assertEqual(sorted(data(out).get("cases") or []), sorted([ci, cf]), dump(out))
        a1, a2 = h.case(ci), h.case(cf)
        self.assertEqual((a1["attention"], a2["attention"]), (1, 1), "текст в TG без внимания (M28)")
        n1 = a1["pause_no"]
        out = st.on_human_intervention(contact=wa(IVAN_WA), kind="text", channel="tg", ref="tg:msg:6",
                                       at=h.clock(), wa_pause_no=None, by=WA_CORE, idem_key="human:tg:tg:msg:6")
        self.assertCode(out, "ok")
        self.assertEqual(h.case(ci)["pause_no"], n1, "второе вмешательство сменило номер внимания")


