class T16StaffAskSeam(K4Case):
    def test_staff_ask_seam_bump_close_tick_zero_posts(self):
        """§13 «шов staff_ask»: подъём → staff_qids_to_close → close (S6) → tick подделки через 3 ч по ЕЁ сроку → 0
        постов в «Агенты» (I41, К4-C32; M26)."""
        h = self.world(label="r16")
        st = h.store("splinter")
        ci = self.ok_case(h, st, r_ivan(booking_id="bk-812"))
        exp_id, res, m = self.ask_and_post(h, st, st, ci, 1)
        out = st.bump_version(ci, reason="new_request", ref="wa:in:4", by=APPROVER,
                              idem_key="bump:%s:1:new_request:wa:in:4" % ci, expect_ver=1)
        self.assertCode(out, "ok")
        qids = data(out).get("staff_qids_to_close") or []
        self.assertIn(res.get("qid"), qids, dump(out))
        for q in qids:
            h.staff_ask.close(q, reason="superseded")
        n = F.run_coro(h.staff_ask.tick(h.telegram.send, agents_chat=AGENTS_CHAT, now=h.clock() + 3 * 3600 + 60))
        self.assertEqual(n, 0)
        self.assertEqual([s for s in h.telegram.sent if s["place"] == "agents"], [])

