    def test_staff_ask_seam_orphan_reply_linked_after_post_found(self):
        """§13: реплай на пост ожидания flight_unknown сохраняется сиротой; при mark_post_result(posted) он связывается
        и получает вердикт в той же транзакции (I40, К4-C32)."""
        h = self.world(label="r16e")
        st = h.store("splinter")
        ci = self.ok_case(h, st, r_ivan(booking_id="bk-812"))
        e0, res0, m0 = self.ask_and_post(h, st, st, ci, 1, q_ru="Байк 6908 готов к выдаче завтра?")
        self.assertCode(m0, "ok", what="прежний вопрос: чаты мест topic/delivery известны хранилищу")
        h.telegram.mode["topic"] = "deliver_then_raise"
        out = self.request_q(st, ci, 1)
        exp_id = data(out)["exp_id"]
        exp = self.claim_one(h, st, exp_id, ("staff_question",))
        res = F.run_coro(h.staff_port.post(exp))
        self.assertIn("unknown", res, dump(res))
        self.assertCode(self.mark(h, st, exp_id, res), "ok")
        self.assertEqual(h.expect(exp_id)["state"], "flight_unknown")
        delivered = [s for s in h.telegram.sent if s["place"] == "topic"][-1]
        out = self.staff_reply(h, st, "7600", delivered["msg_id"], 9001)
        self.assertCode(out, "ok", what="реплай на пост flight_unknown")
        self.assertEqual(verdict(out), "orphan", dump(out))
        orphan = h.one("SELECT * FROM rc_reply_unlinked WHERE msg_id='7600'")
        self.assertEqual((orphan or {}).get("state"), "orphan", dump(orphan))
        out = self.staff_reply(h, st, "7601", "99999", 9001, chat="-1009999999999", thread_id=None,
                               reply_to_is_bot=True)
        self.assertCode(out, "rejected", "not_linked", "реплай в чате без ожидания")
        found = {"posted": [{"place": "topic", "chat": TOPIC_CHAT, "msg_id": delivered["msg_id"],
                             "thread_id": TOPIC_THREAD, "role": "question", "at": delivered["at"]}], "qid": None}
        out = self.mark(h, st, exp_id, found)
        self.assertCode(out, "ok", what="пост найден — mark_post_result(posted) из flight_unknown")
        orphan = h.one("SELECT * FROM rc_reply_unlinked WHERE msg_id='7600'")
        self.assertEqual(orphan["state"], "linked", dump(orphan))
        self.assertTrue(orphan["answer_id"])
        self.assertEqual(h.one("SELECT verdict FROM rc_answer WHERE id=?", (orphan["answer_id"],))["verdict"],
                         "accepted")
        self.assertEqual(h.expect(exp_id)["state"], "answered")

