    def test_approval_yes_and_close_stage_ladder_forbidden_evidence_and_order(self):
        """§13: «да» не даёт 4–5 ни одной дорогой: ступень 4 отвергает staff_answer, approval_yes, agent_text,
        crm_status_read (handover), human_mark со ссылкой ответа и не одобряющего; on_readback(landed) без ступени 4 →
        ступени 5 нет (reason order) (I10, I11, I27, К4-C10, К4-C26; M6, M16, M24)."""
        h = self.world(label="r18l")
        st = h.store("splinter")
        ci = self.ok_case(h, st, r_ivan_future(booking_id="bk-846"))
        tid = self.open_task(h, st, ci, 1)
        exp_id, res, m = self.ask_and_post(h, st, st, ci, 1, task_id=tid)
        a = self.staff_reply(h, st, "7900", self.posted_mid(res, "topic"), 9001)
        self.assertEqual(verdict(a), "accepted")
        answer_ref = "%s:%s" % (TOPIC_CHAT, "7900")
        before = h.counts()
        bad = (
            ("staff_answer", {"kind": "staff_answer", "ref": answer_ref}, APPROVER, "evidence_forbidden"),
            ("approval_yes", {"kind": "approval_yes", "ref": "%s:8001" % INBOX_CHAT}, APPROVER, "evidence_forbidden"),
            ("agent_text", {"kind": "agent_text", "ref": "wa:out:1"}, AGENT, "evidence_forbidden"),
            ("human_mark со ссылкой ответа", hm(answer_ref), APPROVER, "evidence_forbidden"),
            ("human_mark не одобряющего", hm("btn:done:x", author_id=2002), HUMAN_NOT_APPROVER, "approver_unknown"),
        )
        for label, ev, by, reason in bad:
            out = st.record_stage(ci, task_id=tid, stage="physically_done", evidence=ev, by=by,
                                  idem_key="stage:%s:physically_done:%s" % (tid, label))
            self.assertCode(out, "rejected", reason, "ступень 4 по %s" % label)
        out = st.record_stage(ci, task_id=tid, stage="result_recorded",
                              evidence={"kind": "staff_answer", "ref": answer_ref}, by=APPROVER,
                              idem_key="stage:%s:result_recorded:sa" % tid)
        self.assertCode(out, "rejected", "evidence_forbidden", "ступень 5 по ответу")
        self.assertNoWrites(h, before, "отказы ступеней")
        ho = self.open_task(h, st, ci, 1, kind="handover", ref="card:ho:1")
        out = st.record_stage(ci, task_id=ho, stage="physically_done",
                              evidence={"kind": "crm_status_read", "ref": "crm:846:1", "booking_id": "bk-846",
                                        "status": "В аренде", "row": 846, "read_at": h.clock()},
                              by=SPL, idem_key="stage:%s:physically_done:crm" % ho)
        self.assertCode(out, "rejected", "evidence_forbidden", "crm_status_read на ступени 4 выдачи")
        rb, out = self.readback_landed(h, st, ci, tid, 1, check_ok=False)
        self.assertCode(out, "ok", what="on_readback(landed) без ступени 4")
        self.assertIsNone(data(out).get("stage"), dump(out))
        self.assertIn("order", full(out))
        self.assertNotIn("result_recorded", h.stages(tid), "ступень 5 без 4 (M16)")
        self.assertEqual(h.task(tid)["state"], "open")
        self.assertEqual(h.expect(rb)["state"], "answered")

    def test_approval_yes_and_close_record_delivery_stage6_on_done_task(self):
        """§13: record_delivery на done-задаче → ступень 6, top_stage=6, задача done, закрывающее обязательство
        notify_final (intent=final) закрыто stage; record_stage(client_notified) → rejected(bad_transition)
        (I12, К4-C10)."""
        h = self.world(label="r18m")
        wa_st, spl = h.store("wa"), h.store("splinter")
        cb = self.ok_case(h, spl, r_boris(booking_id="bk-845"))
        d = self.drive_to_stage5(h, wa_st, spl, cb)
        tid = d["task_id"]
        before = h.counts()
        out = spl.record_stage(cb, task_id=tid, stage="client_notified",
                               evidence={"kind": "wa_delivery", "ref": "wamid.X", "notice_id": "RN-x",
                                         "wamid": "wamid.X", "status": "delivered", "at": h.clock()},
                               by=SPL, idem_key="stage:%s:client_notified" % tid)
        self.assertCode(out, "rejected", "bad_transition", "record_stage(client_notified)")
        self.assertNoWrites(h, before, "bad_transition")
        out = self.propose(h, wa_st, cb, tid, intent="final")
        self.assertCode(out, "ok", what="намерение final")
        nid = self.notice_id_of(h, out, cb)
        rv = h.notice_row(nid)["row_ver"]
        self.assertCode(wa_st.claim_notice(nid, by=WA_CORE, idem_key="nclaim:%s:%d" % (nid, rv), expect_row_ver=rv),
                        "ok")
        draft = h.notice.propose(notice_id=nid, case_id=cb, case_ver=1, intent="final", facts=[])["draft_id"]
        rv = h.notice_row(nid)["row_ver"]
        self.assertCode(wa_st.mark_notice(nid, state="drafted", by=WA_CORE, idem_key="nst:%s:drafted:%s" % (nid, draft),
                                          expect_row_ver=rv, draft_id=draft), "ok")
        wamid = h.notice.human_press(nid)
        # К4 круг 2 (C10): ядро WA знает wamid в момент отправки — привязка отправки до любого статуса доставки
        self.assertCode(wa_st.record_notice_sent(nid, draft_id=draft, wamid=wamid, at=h.clock(),
                                                 source=h.src(name="wa send_text", ref="draft:%s" % draft,
                                                              method="door"),
                                                 by=WA_CORE, idem_key="nsent:%s:%s:%s" % (nid, draft, wamid)),
                        "ok", what="привязка отправки")
        h.clock.advance(30)
        h.delivery.statuses[wamid] = ("delivered", h.clock())
        stt = h.delivery.status(wamid)
        out = wa_st.record_delivery(nid, wamid=wamid, status=stt["status"], at=stt["at"],
                                    source=h.src(name="wa part_status", ref=wamid, method="event"), by=WA_CORE,
                                    idem_key="ndel:%s:%s:%s" % (nid, wamid, stt["status"]))
        self.assertCode(out, "ok", what="record_delivery")
        t = h.task(tid)
        self.assertEqual((t["state"], t["top_stage"]), ("done", 6), dump(t))
        self.assertIn("client_notified", h.stages(tid))
        self.assertEqual(h.notice_row(nid)["state"], "delivered")
        nf = h.obligation(cb, "client", "notify_final")
        self.assertEqual((nf["state"], nf["closed_by"]), ("closed", "stage"), dump(nf))
        self.assertEqual(h.counters.client_sends, 0)


