# 19. Сопоставление п.1: state
# =====================================================================================================================


class T19MappingState(K4Case):
    def test_mapping_state_bike_state_is_reference_not_evidence(self):
        """§13 «сопоставление п.1: state»: «в аренде» в листе и booking_id чужой брони → факт bike_state с флагом
        foreign_booking; ступени 4/5 по нему → evidence_forbidden; bike/return не закрыт; resolve и bind_cash того же
        вызова не меняются (I44, К4-C37; M29)."""
        h = self.world(label="r19")
        st = h.store()
        row = r_ivan(booking_id="bk-812")
        ci = self.ok_case(h, st, row)
        rows = [row]
        item = F.state_item(BIKE_NMAX, status="в аренде", booking_id="bk-999-other", client="Борис",
                            updated="2026-10-13 10:05")
        h.bridge.states[BIKE_NMAX] = item
        sp = h.state_port.get(BIKE_NMAX)
        self.assertTrue(sp.get("ok"), dump(sp))
        binding = {"booking_id": "bk-812", "bike_name": BIKE_NMAX, "status_seen": "В аренде"}
        bsf = RR.bike_state_fact(sp["item"], binding)
        self.assertIn("foreign_booking", bsf.get("flags") or [], dump(bsf))
        self.assertIn("status_mismatch", RR.bike_state_fact(sp["item"], dict(binding, status_seen="Завершена"))
                      .get("flags") or [])
        self.assertEqual(RR.bike_state_fact(dict(sp["item"], bike=BIKE_PCX), binding).get("code"), "foreign_bike")
        r0 = st.resolve(purpose="return", rows=rows, moment=MOMENT, observed_at=h.clock(), plate="6908")
        f_a, _ = h.cash_fact(2081, 3000, "2026-10-09", booking_id="bk-999-other")
        c0 = st.bind_cash(ci, cash_fact=f_a, rows=rows, source=h.src(name=CASH_SRC, ref="строка 2081"), by=CASH_BY,
                          idem_key=cash_idem(ci, f_a))
        fk = ["bike_state", BIKE_NMAX, item["updated"]]
        s = {"name": STATE_SRC, "ref": BIKE_NMAX, "method": "door", "read_at": sp["read_at"],
             "observed_at": sp["observed_at"]}
        out = st.record_fact(ci, kind="bike_state", value=bsf["value"], source=s, scope="case", by=CODE,
                             idem_key="fact:%s:%s:%r" % (ci, json.dumps(fk, ensure_ascii=False), s["observed_at"]),
                             fkey=fk)
        self.assertCode(out, "ok", what="факт bike_state")
        r1 = st.resolve(purpose="return", rows=rows, moment=MOMENT, observed_at=h.clock(), plate="6908")
        self.assertEqual((r1.get("code"), r1.get("case_id")), (r0.get("code"), r0.get("case_id")), dump([r0, r1]))
        f_b, _ = h.cash_fact(2082, 3000, "2026-10-09", booking_id="bk-999-other")
        c1 = st.bind_cash(ci, cash_fact=f_b, rows=rows, source=h.src(name=CASH_SRC, ref="строка 2082"), by=CASH_BY,
                          idem_key=cash_idem(ci, f_b))
        self.assertEqual((c1.get("code"), rcode(c1)), (c0.get("code"), rcode(c0)), dump([c0, c1]))
        tid = self.open_task(h, st, ci, 1, kind="return", ref="card:ret:1")
        before = h.counts()
        for stage in ("physically_done", "result_recorded"):
            out = st.record_stage(ci, task_id=tid, stage=stage,
                                  evidence={"kind": "bike_state", "ref": "state:%s:%s" % (BIKE_NMAX, item["updated"]),
                                            "bike": BIKE_NMAX, "status": "в аренде"},
                                  by=SPL, idem_key="stage:%s:%s:bike_state" % (tid, stage))
            self.assertCode(out, "rejected", "evidence_forbidden", "ступень %s по bike_state" % stage)
        self.assertNoWrites(h, before, "отказы bike_state")
        self.assertNotEqual(h.obligation(ci, "bike", "return")["state"], "closed")
        self.assertIn("foreign_booking", full(st.case_view(ci).get("bike")))


