# 20. Явное представление дела (Д2)
# =====================================================================================================================


class T20CaseViewD2(K4Case):
    PARTS = ("case", "client", "rental", "bike", "documents", "money", "obligations_other", "facts", "tasks",
             "expectations", "answers", "orphans", "notices", "blockers", "allowed_actions", "read_at")

    def assertSrc(self, s, row, what):
        self.assertIsInstance(s, dict, "%s: src нет" % what)
        for k in SRC_KEYS:
            self.assertIn(k, s, "%s: в src нет %s: %s" % (what, k, dump(s)))
        col = {"source": row["source"], "ref": row["ref"], "method": row["method"], "read_at": row["read_at"],
               "observed_at": row["observed_at"], "case_ver": row["case_ver"]}
        for k in ("source", "ref", "method", "case_ver"):
            self.assertEqual(s[k], col[k], "%s: src.%s ≠ колонке строки: %s vs %s" % (what, k, dump(s), dump(col)))
        for k in ("read_at", "observed_at"):
            self.assertAlmostEqual(float(s[k]), float(col[k]), places=3, msg="%s: src.%s ≠ колонке" % (what, k))

    def test_case_view_d2_parts_and_src_from_columns(self):
        """§13 «явное представление дела (Д2)»: части клиент, аренда, байк, документы, деньги, факты — отдельными
        ключами; у каждого элемента 6 полей src, значения — из колонок строки (rc_contact, rc_rental, rc_document,
        rc_obligation); у дела Бориса — passport_deposit; version инструмента case = "case_ver:<n>", поля версии
        внешнего источника нет (I22, К4-C36, F2 К3)."""
        h = self.world(label="r20")
        st = h.store()
        row = r_ivan(booking_id="bk-812")
        ci = self.ok_case(h, st, row)
        cb = self.ok_case(h, st, r_boris(booking_id="bk-845"))
        fact, _ = h.cash_fact(2091, 3000, "2026-10-01", booking_id="bk-812", description="залог")
        self.assertCode(st.bind_cash(ci, cash_fact=fact, rows=[row], source=h.src(name=CASH_SRC, ref="строка 2091"),
                                     by=CASH_BY, idem_key=cash_idem(ci, fact)), "ok")
        h.contract(233, IVAN_DOC, "Иван", "2026-10-01", BIKE_NMAX, IVAN_U, IVAN_SIGNED)
        cr = h.contract_port.find(number=IVAN_WA, rental=row, phone=IVAN_WA)
        self.assertCode(st.record_document(ci, kind="contract_signed", ext_id=IVAN_DOC, status="verified",
                                           source=h.src(name=CONTRACT_SRC, ref="строка 233"), by=CODE,
                                           idem_key="doc:%s:contract_signed:%s:%s" % (ci, IVAN_DOC, IVAN_SIGNED),
                                           signed_at=IVAN_SIGNED, reg_row=233, rental_id=h.rental(ci)["id"],
                                           contract_result=cr), "ok")
        cv = st.case_view(ci)
        for part in self.PARTS:
            self.assertIn(part, cv, "в case_view нет части %s" % part)
        for path, x in walk(cv):
            if isinstance(x.get("src"), dict):
                for k in SRC_KEYS:
                    self.assertIn(k, x["src"], "%s: src без %s" % (path, k))
        self.assertIsInstance((cv.get("client") or {}).get("src"), dict, "client без src")
        self.assertEqual(cv["client"].get("name_seen"), "Иван")
        contacts = [x for _p, x in walk(cv.get("client")) if "channel" in x and "value_masked" in x]
        self.assertTrue(contacts, dump(cv.get("client")))
        for c in contacts:
            rowc = [r for r in h.contacts(ci) if r["channel"] == c["channel"] and r["value"].endswith(
                str(c["value_masked"])[-4:])]
            self.assertEqual(len(rowc), 1, dump(c))
            self.assertNotIn(rowc[0]["value"], full(c), "номер не замаскирован")
            self.assertSrc(c.get("src"), rowc[0], "контакт")
        cur = [x for _p, x in walk(cv.get("rental")) if "anchor" in x and "crm_row_seen" in x]
        self.assertTrue(cur, dump(cv.get("rental")))
        self.assertSrc(cur[0].get("src"), h.rental(ci), "аренда")
        docs = [x for _p, x in walk(cv.get("documents")) if "ext_id" in x and "src" in x]
        self.assertTrue([d for d in docs if d["ext_id"] == IVAN_DOC], dump(cv.get("documents")))
        for d in docs:
            r = h.one("SELECT * FROM rc_document WHERE case_id=? AND ext_id=?", (ci, d["ext_id"]))
            self.assertSrc(d["src"], r, "документ %s" % d["ext_id"])
        money = [x for _p, x in walk(cv.get("money")) if "role" in x and "direction" in x and "src" in x]
        self.assertTrue(money, dump(cv.get("money")))
        for mny in money:
            r = h.obligation(ci, "money", mny["role"])
            self.assertSrc(mny["src"], r, "деньги %s" % mny["role"])
        self.assertIn("2091", full(cv.get("money")), "касса не видна в cash[] обязательства")
        bike = cv.get("bike")
        self.assertIsInstance(bike, dict)
        self.assertEqual((bike.get("plate"), bike.get("bike_name")), ("6908", BIKE_NMAX), dump(bike))
        cvb = st.case_view(cb)
        pd = [x for _p, x in walk(cvb.get("documents")) if x.get("kind") == "passport_deposit"]
        self.assertTrue(pd and pd[0].get("status") == "unverified", dump(cvb.get("documents")))
        ffa = st.facts_for_agent(ci)
        self.assertEqual(ffa.get("tool"), "case")
        self.assertEqual(ffa.get("version"), "case_ver:%d" % h.ver(ci), dump(ffa))
        kinds = set(f.get("kind") for f in ffa.get("facts") or [])
        for k in ("case", "case_client", "case_rental", "case_bike", "case_money", "case_document"):
            self.assertIn(k, kinds, "facts_for_agent без %s: %s" % (k, sorted(kinds)))
        for f in ffa.get("facts") or []:
            self.assertIsInstance(f.get("src"), dict, "факт агента без src: %s" % dump(f))
            for k in SRC_KEYS:
                self.assertIn(k, f["src"], dump(f))
            if f.get("kind") == "case_document":
                self.assertIn("doc_kind", f, dump(f))
        for path, x in walk([cv, ffa]):
            for key in ("source_ver", "source_version", "ext_version"):
                if key in x:
                    self.assertIsNone(x[key], "%s: версия внешнего источника заполнена: %s" % (path, dump(x)))

    def test_case_view_d2_link_drift_hides_rental_money_documents(self):
        """§13 та же строка: при link_state≠ok агенту не отдаются case_rental, case_bike, case_money, case_document;
        reason несёт вопрос confirm_link (I37, К4-C36)."""
        h = self.world(label="r20b")
        st = h.store()
        row = r_ivan(booking_id="bk-812")
        ci = self.ok_case(h, st, row)
        out = self.reconcile(h, st, ci, [with_(row, name="Пётр Иванов")])
        self.assertCode(out, "unknown", "link_confirmation", "смена имени при том же booking_id")
        self.assertEqual(h.case(ci)["link_state"], "drift")
        ffa = st.facts_for_agent(ci)
        kinds = set(f.get("kind") for f in ffa.get("facts") or [])
        self.assertFalse(kinds & {"case_rental", "case_bike", "case_money", "case_document"}, sorted(kinds))
        self.assertTrue((ffa.get("reason") or "").strip(), dump(ffa))


