# 21. Полный демо-случай (CONTRACT §14)
# =====================================================================================================================


class T21FullDemo(K4Case):
    def test_full_demo_variant_a_readiness_until_notice_intent(self):
        """§13 «полный демо-случай» (CONTRACT §14, вариант А): Д1–Д14 по порядку, один case_id Бориса, case_ver=1 на всех
        шагах, дело Ивана не меняется после Д2; в конце — намерение (intent), черновика нет; постов подделки staff_ask
        2, эскалаций 0, вызовов NoticePort 0, отправок клиенту 0, сети 0 (К4-C35, К4-C18; M6, M27)."""
        h = self.world(label="demoA")
        wa_st, spl = h.store("wa"), h.store("splinter")

        def v1(step):
            self.assertEqual(h.ver(cb), 1, "%s: case_ver дела Бориса ≠ 1" % step)

        # Д1
        self.assertEqual((wa_st.store_id, spl.store_id), (h.store_id, h.store_id), "Д1: store_id один")
        # Д2
        boris, ivan = r_boris(), r_ivan()
        cb = self.ok_case(h, spl, boris)
        ci = self.ok_case(h, spl, ivan)
        got = set((o["kind"], o["role"]) for o in h.obligations(cb))
        for need in (("bike", "handover"), ("bike", "return"), ("money", "rent"), ("money", "deposit"),
                     ("document", "passport_return"), ("client", "notify_final")):
            self.assertIn(need, got, "Д2: нет %s/%s" % need)
        dep = h.obligation(cb, "money", "deposit")
        self.assertEqual(dep["state"], "unknown")
        dep_why = [json.loads(e["payload"]).get("why") for e in h.events(cb, "obligation_opened")
                   if json.loads(e["payload"]).get("obligation_id") == dep["id"]]
        self.assertEqual(dep_why, ["deposit_passport"], "Д2: why=deposit_passport")
        self.assertEqual(h.obligation(cb, "client", "notify_final")["state"], "unknown")
        self.assertEqual([d["status"] for d in h.documents(cb) if d["kind"] == "passport_deposit"], ["unverified"])
        ivan_case, ivan_events = h.case(ci), len(h.events(ci))
        self.assertEqual(h.ver(ci), 1)
        v1("Д2")
        # Д3
        out = wa_st.on_client_inbound(contact=wa(BORIS_WA), ref="wa:in:501", at=h.clock(), by=WA_CORE,
                                      idem_key="in:wa:wa:in:501")
        self.assertCode(out, "ok", what="Д3")
        self.assertIn(cb, full([e for e in h.events() if e["type"] == "client_inbound"]),
                      "Д3: событие client_inbound без дела Бориса")
        v1("Д3")
        # Д4
        r = wa_st.resolve(purpose="client", rows=[ivan, boris], moment=MOMENT, observed_at=h.clock(), intent="future",
                          contact=wa(BORIS_WA))
        self.assertEqual((r.get("code"), r.get("case_id")), ("found", cb), "Д4: %s" % dump(r))
        ffa = wa_st.facts_for_agent(cb)
        self.assertEqual(ffa.get("outcome"), "fact", dump(ffa))
        kinds = set(f.get("kind") for f in ffa.get("facts") or [])
        for k in ("case", "case_client", "case_rental", "case_bike", "case_money", "case_document"):
            self.assertIn(k, kinds, "Д4: части %s нет: %s" % (k, sorted(kinds)))
        # Д5
        tid = self.open_task(h, wa_st, cb, 1, by=AGENT)
        v1("Д5")
        # Д6
        out = self.request_q(wa_st, cb, 1, task_id=tid, by=AGENT)
        self.assertCode(out, "ok", what="Д6")
        exp_id = data(out)["exp_id"]
        self.assertEqual(h.expect(exp_id)["state"], "planned")
        v1("Д6")
        # Д7
        exp = self.claim_one(h, spl, exp_id, ("staff_question",))
        res = F.run_coro(h.staff_port.post(exp))
        self.assertCode(self.mark(h, spl, exp_id, res), "ok", what="Д7")
        self.assertEqual(h.expect(exp_id)["state"], "waiting")
        posts = dict((p["place"], p) for p in h.posts(exp_id))
        self.assertEqual((posts["topic"]["msg_id"], posts["topic"]["thread_id"], posts["delivery"]["msg_id"]),
                         ("7001", TOPIC_THREAD, "7002"), dump(posts))
        self.assertEqual(h.stages(tid), ["question_sent"])
        self.assertIsNone(h.expect(exp_id)["business_due_at"])
        self.assertEqual(spl.due_expectations(now=h.clock() + 48 * 3600) or [], [], "Д7: due по возрасту (M27)")
        v1("Д7")
        # Д8
        spl = h.restart("splinter")
        out = spl.recover(by=SPL)
        self.assertCode(out, "ok", what="Д8 recover")
        self.assertEqual((int(data(out).get("expect") or 0), int(data(out).get("escalation") or 0),
                          int(data(out).get("notice") or 0)), (0, 0, 0), dump(out))
        self.assertEqual(h.expect(exp_id)["state"], "waiting")
        v1("Д8")
        # Д9
        h.clock.advance(600)
        a = self.staff_reply(h, spl, "7010", "7001", 9001)
        self.assertCode(a, "ok", what="Д9")
        self.assertEqual(verdict(a), "accepted", dump(a))
        self.assertEqual(h.expect(exp_id)["state"], "answered")
        self.assertEqual(h.stages(tid), ["question_sent", "answer_received"])
        self.assertTrue(h.facts(cb, "staff_answer"), "Д9: факт staff_answer")
        v1("Д9")
        # Д10, Д11
        for stage, act in (("task_accepted", "btn:accept:1"), ("physically_done", "btn:done:1")):
            out = spl.record_stage(cb, task_id=tid, stage=stage, evidence=hm(act), by=APPROVER,
                                   idem_key="stage:%s:%s" % (tid, stage))
            self.assertCode(out, "ok", what=stage)
            v1(stage)
        # Д12
        self.readback_landed(h, spl, cb, tid, 1)
        t = h.task(tid)
        self.assertEqual((t["state"], t["top_stage"]), ("done", 5), dump(t))
        self.assertEqual(h.stages(tid),
                         ["question_sent", "answer_received", "task_accepted", "physically_done", "result_recorded"])
        v1("Д12")
        # Д13
        allowed = spl.allowed_actions(cb)
        self.assertIn("propose_client_notice", full(allowed), "Д13: %s" % dump(allowed))
        # Д14
        out = self.propose(h, spl, cb, tid)
        self.assertCode(out, "ok", what="Д14")
        nid = self.notice_id_of(h, out, cb)
        self.assertEqual(h.notice_row(nid)["state"], "intent")
        self.assertIsNone(h.notice_row(nid)["draft_id"], "Д14: черновик создан")
        self.assertTrue(h.events(cb, "notice_proposed"))
        v1("Д14")
        self.assertEqual(h.case(ci), ivan_case, "дело Ивана изменилось")
        self.assertEqual(len(h.events(ci)), ivan_events)
        c = h.counters.snapshot()
        self.assertEqual((c["staff_posts"], c["escalations"], c["notice_calls"], c["client_sends"], c["net"]),
                         (2, 0, 0, 0, 0), "счётчики демо: %s" % dump(c))
        self.assertEqual(F.net_attempts(), 0, F.net_log())

    def test_full_demo_variant_b_params_default_stops(self):
        """§13 / CONTRACT §14 вариант Б (К4-C17): с PARAMS_DEFAULT агент → rejected(param_unknown) (AUTO_ASK); от
        одобряющего проходит; посты с addressee_ids="UNKNOWN"; ответ → reference_author_unverified, ожидание waiting,
        ступени 2 нет; due_expectations(+48 ч) пуст; allowed_actions без propose_client_notice (I16)."""
        h = self.world(label="demoB", params=params_default())
        wa_st, spl = h.store("wa"), h.store("splinter")
        approver = default_approver()
        cb = self.ok_case(h, spl, r_boris())
        self.ok_case(h, spl, r_ivan())
        before = h.counts()
        out = wa_st.open_task(cb, kind="readiness", ref="wa:in:501", by=AGENT,
                              idem_key="task:%s:1:readiness:wa:in:501:agent" % cb, expect_ver=1)
        self.assertCode(out, "rejected", "param_unknown", "Д5 от агента (AUTO_ASK)")
        out = self.request_q(wa_st, cb, 1, by=AGENT)
        self.assertCode(out, "rejected", "param_unknown", "Д6 от агента (AUTO_ASK)")
        self.assertNoWrites(h, before, "отказы агента")
        tid = self.open_task(h, wa_st, cb, 1, by=approver)
        exp_id, res, m = self.ask_and_post(h, wa_st, spl, cb, 1, task_id=tid, by=approver)
        self.assertCode(m, "ok", what="Д7")
        posts = h.posts(exp_id)
        self.assertTrue(posts)
        for p in posts:
            self.assertEqual(p["addressee_ids"], "UNKNOWN", dump(p))
        out = self.staff_reply(h, spl, "7010", self.posted_mid(res, "topic"), 9001)
        self.assertCode(out, "ok", what="Д9")
        self.assertEqual(verdict(out), "reference_author_unverified", dump(out))
        self.assertEqual(h.expect(exp_id)["state"], "waiting")
        self.assertNotIn("answer_received", h.stages(tid))
        self.assertEqual(spl.due_expectations(now=h.clock() + 48 * 3600) or [], [])
        self.assertNotIn("propose_client_notice", full(spl.allowed_actions(cb)))
        self.assertEqual(h.counters.client_sends + F.net_attempts(), 0)


# =====================================================================================================================
# 22. Проверки ловят порчу
# =====================================================================================================================


class T22ChecksCatchCorruption(unittest.TestCase):
    NEED = tuple(["M%d" % i for i in range(1, 32)] + ["M1b", "M10b", "M11b", "M14b", "M31b", "M31c"])

    def test_checks_catch_corruption_mutant_inventory(self):
        """§13 «проверки ловят порчу» (К4-C20): tests/rental_case_mutants.py обязан перечислять M1–M31 с M1b, M10b,
        M11b, M14b, M31b, M31c. Сам прогон мутантов — независимая проверка (CONTRACT §15 п.4); здесь — полнота
        перечня. Файла ещё нет → пропуск с причиной (не зелёный)."""
        path = os.path.join(HERE, "rental_case_mutants.py")
        if not os.path.isfile(path):
            self.skipTest("tests/rental_case_mutants.py ещё не написан — строку §13 проверяет прогон мутантов (К4-C20)")
        with open(path, encoding="utf-8") as f:
            src = f.read()
        missing = [m for m in self.NEED if not re.search(r"(?<![A-Za-z0-9])%s(?![0-9a-z])" % m, src)]
        self.assertEqual(missing, [], "мутанты не перечислены: %s" % missing)


