        ivan = r_ivan(booking_id="bk-812")
        ci = self.ok_case(h, st, ivan)
        before = h.counts()
        out = st.rebind_rental(ci, row=with_(ivan, bike=BIKE_PCX), reason="bike_changed", by=HUMAN_NOT_APPROVER,
                               source=h.src(), idem_key="rebind:%s:1:r3" % ci, expect_ver=1)
        self.assertCode(out, "rejected", "approver_unknown", what="rebind_rental не одобряющим при UNKNOWN")
        self.assertNoWrites(h, before, "rebind_rental не одобряющим")
        self.assertEqual((h.rental(ci)["plate"], h.ver(ci)), ("6908", 1), dump(h.rental(ci)))
        self.assertEqual(h.events(ci, "rental_rebound"), [])
        h2 = self.world(label="r3rb_ok")
