        before = h.counts()
        out = st.record_stage(cid, task_id=tid, stage="physically_done",
                              evidence=hm("btn:done:%s" % tid, author_id=2002), by=HUMAN_NOT_APPROVER,
                              idem_key="stage:%s:physically_done:r3v4" % tid)
        self.assertCode(out, "rejected", "approver_unknown", what="human_mark не одобряющим при UNKNOWN")
        self.assertNoWrites(h, before, "human_mark не одобряющим")
        self.assertEqual(h.stages(tid), [])
        self.assertEqual(h.task(tid)["top_stage"], 0, dump(h.task(tid)))
        h2 = self.world(label="r3v4hmok")                 # контроль: та же ступень одобряющим при обычных params
        st2 = h2.store("splinter")
        cid2 = self.ok_case(h2, st2, r_ivan(booking_id="bk-812"))
